COLLNT("sharhsunnaur",{"776":["شعیب کے متعلق خبر دیتے ہوئے اللہ تعالیٰ فرماتے ہیں:","﴿ عَلَى أَنْ تَأْجُرَنِي ثَمَانِيَ حِجَجٍ ﴾ [سورہ قصص: ۲۷]","’’اس شرط پر کہ تو آٹھ سال تک میری ملازمت کرے۔‘‘","نیز ارشاد باری ہے:","﴿ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ ﴾ [سورہ قصص: ۲۶]","’’بہترین مزدور وہ ہے جو طاقتور اور امانتدار ہو۔‘‘","سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم اور ابو بکر صدیق رضی اللہ عنہ نے بنو لیث میں سے ایک ماہر آدمی کو مزدوری دے کر راستہ دکھانے کے لیے مقرر کیا جو کہ کفار قریش کے دین پر قائم تھا۔ دونوں نے اپنی سواریاں اس کے سپرد کیں اور تین دن بعد غار ثور میں آنے کا وعدہ کیا۔ (صحیح بخاری: ۲۲۶۳) اس میں دلیل ہے کہ اگر کوئی آدمی ملازم رکھتا ہے تا کہ وہ تین دن بعد کام کرے یا سال بعد کام کرے تو جائز ہے اور دونوں اپنی شرائط پوری کریں گے۔"],"788":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَيَسْأَلُونَكَ عَنِ الْيَتَامَى قُلْ إِصْلَاحٌ لَهُمْ خَيْرٌ ﴾ [سورہ بقرہ: ۲۲۰]","’’اور آپ سے یتیموں کے بارے میں سوال کرتے ہیں، آپ کہہ دیجیے ان کی خیر خواہی کرنا بہتر ہے۔‘‘","نیز اللہ تعالی کا ارشاد ہے:","﴿ وَلَا تَأْكُلُوهَا إِسْرَافًا وَبِدَارًا أَنْ يَكْبَرُوا ﴾ [سورہ نساء: ۶]","’’اور ان کے بڑے ہو جانے کے ڈر سے ان کے مالوں کو جلدی جلدی فضول خرچی میں تباہ نہ کر دو۔‘‘","بادرة کا معنی ہے جلدی کرنا، اللہ تعالی فرماتا ہے، اس خوف سے کہ یتیم جوان ہو کر اپنا مال لے لے گا تم جلدی جلدی اس کو ٹھکانے لگا دو اور شاہ خرچیوں میں اڑا دو۔ اللہ عزوجل کا فرمان ہے:","﴿ وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِ ﴾ [سورہ نساء: ۶]","’’مسکین محتاج ہو تو دستور کے مطابق واجبی طور سے کھا لے۔‘‘","سیدہ عائشہ رضی اللہ عنہا نے فرمایا: یہ آیت کریمہ یتیم کے سرپرست اور ولی کے متعلق نازل ہوئی ہے جو یتیم کے مال کا ذمہ دار اور محافظ ہے۔ اگر یتیم کے مال اور جائداد کی نگرانی کرنے والا فقیر اور مفلس ہے تو وہ دستور کے مطابق معاشرتی اصول وضوابط کو ملحوظ رکھتے ہوئے اپنی نگرانی کا معاوضہ وصول کر سکتا ہے۔ (صحیح بخاری: ۴۵۷۵) مروی ہے کہ انھوں نے بیان کیا کہ وصی (جس کو یتیم کی سرپرستی کی وصیت کی گئی ہے) یتیم کے مال سے بقدر اپنی مزدوری کے لے سکتا ہے، ایک قول یہ بھی ہے کہ وہ دستور کے مطابق واجبی طور سے کھا لے جس سے اس کی ضرورت پوری ہو جائے۔"],"791":["ارشاد باری تعالیٰ ہے:","﴿ لِلرِّجَالِ نَصِيبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالْأَقْرَبُونَ وَلِلنِّسَاءِ نَصِيبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ نَصِيبًا مَفْرُوضًا ﴾ [سورہ نساء: ۷]","’’مردوں کے لیے اس میں سے ایک حصہ ہے جو والدین اور قریبی رشتہ دار چھوڑ جائیں اور عورتوں کے لیے بھی اس میں سے ایک حصہ ہے جو والدین اور قریبی رشتہ دار چھوڑ جائیں، اس میں سے جو اس (مال) سے تھوڑا ہو یا بہت، اس حال میں کہ مقرر کیا ہوا حصہ ہے۔‘‘","’’نَصِيبًا مَفْرُوضًا‘‘ سے مراد مقرر کیا ہوا حصہ ہے، لفظ ’’الْفَرْض‘‘ کے معنی ’’توقیت‘‘ کے ہیں، اصل میں اس کا معنی کاٹنا ہے، جب آپ مال کا کچھ حصہ کسی کو عطا کرتے ہیں تو کہتے ہیں: فرضت لفلان، إذا قطعت له من المال شيئًا."],"792":["ارشادِ باری تعالی ہے:","﴿ يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ فَإِنْ كُنَّ نِسَاءً فَوْقَ اثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ﴾ [سورہ نساء: ۱۱]","’’اللہ تمہیں تمہاری اولاد کے بارے میں تاکیدی حکم دیتا ہے، مرد کے لیے دو عورتوں کے حصے کے برابر حصہ ہے، پھر اگر وہ دو سے زیادہ عورتیں (ہی) ہوں، تو ان کے لیے اس کا دو تہائی ہے جو اس نے چھوڑا۔‘‘"],"793":["ارشادِ باری تعالی ہے:","﴿ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلَالَةِ إِنِ امْرُؤٌ هَلَكَ لَيْسَ لَهُ وَلَدٌ وَلَهُ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ ﴾ [سورہ نساء: ۱۷۶]","’’کہہ دیجیے اللہ تمھیں کلالہ کے بارے میں فتویٰ دیتا ہے، اگر کوئی آدمی مر جائے جس کی کوئی اولاد نہ ہو اور اس کی ایک بہن ہو تو اس کے لیے اس کا نصف ہے جو اس نے چھوڑا۔‘‘"],"794":["ارشادِ باری تعالی ہے:","﴿ فَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَوَرِثَهُ أَبَوَاهُ فَلِأُمِّهِ الثُّلُثُ فَإِنْ كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ ﴾ [سورہ نساء: ۱۱]","’’اگر میت کی اولاد نہ ہو اور اس کے والدین اس کے وارث بن رہے ہوں تو ماں کو ایک تہائی ملے گا اور اس کے بھائی موجود ہوں تو ماں کو چھٹا حصہ ملے گا۔‘‘"],"795":["ارشادِ باری تعالی ہے:","﴿ فَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَوَرِثَهُ أَبَوَاهُ فَلِأُمِّهِ الثُّلُثُ فَإِنْ كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ ﴾ [سورہ نساء: ۱۱]","’’اگر میت کی اولاد نہ ہو اور اس کے والدین اس کے وارث بن رہے ہوں تو ماں کو ایک تہائی ملے گا اور اس کے بھائی موجود ہوں تو ماں کو چھٹا حصہ ملے گا۔‘‘"],"804":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَاجًا وَذُرِّيَّةً ﴾ [سورہ رعد: ۳۸]","’’ہم نے آپ سے پہلے بہت رسول بھیجے ہیں اور ہم نے ان سب کو بیوی بچوں والا بنایا تھا۔‘‘"],"805":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ﴾ ’’اور یہ دعا کرتے ہیں کہ اے ہمارے پروردگار! تو ہمیں ہماری بیویوں اور اولاد سے آنکھوں کی ٹھنڈک عطا فرما۔‘‘ (سورہ فرقان: ۷۴)"],"811":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ ﴾ [سورہ احزاب: ۳۲]","’’تم نرم لہجے سے بات نہ کرو کہ جس دل میں روگ ہو وہ کوئی برا خیال کرے۔‘‘"],"814":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ ﴾ [سورہ نور: ۳۲]","’’تم میں سے جو مرد عورت بے نکاح کے ہوں ان کا نکاح کر دو۔‘‘","نیز اللہ تعالیٰ کا فرمان ہے:","﴿ فَانْكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ ﴾ [سورہ نساء: ۲۵]","’’ان کے مالکوں کی اجازت سے ان سے نکاح کر لو۔‘‘","(الْأَيَامَى) ایسی عورت کو کہتے ہے جس کا خاوند فوت ہو گیا ہو یا جس نے اپنی بیوی کو طلاق دے دی ہو، کنواری لڑکی کو بھی (آیم) کہہ لیا جاتا ہے کیونکہ اس کا بھی خاوند نہیں ہوتا) گویا ’’آیم‘‘ ایسی عورت کو کہا جاتا ہے جس کا خاوند نہ ہو، جس میں کنواری، بیوہ اور مطلقہ تینوں آجاتی ہیں) اور ایسے مرد کو بھی آیم کہتے ہیں جس کی بیوی نہ ہو۔ عورت کے لیے ’’آیم‘‘ اور ’’آیمة‘‘ دونوں الفاظ مستعمل ہیں۔ چونکہ یہ لفظ عربی زبان میں زیادہ تر خواتین کے لیے استعمال ہوتا ہے اس لیے انہیں آیم کہہ دیا جاتا ہے اور یہ لفظ مردوں کے لیے کم استعمال ہونے کی بنا ایسا لگتا ہے کہ عورتوں سے مستعار ادھار لیا گیا ہے۔ (حالانکہ لفظ ’’آیم‘‘ اپنی لفظی ساخت کے لحاظ سے مذکر ہے)۔"],"817":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَلَمَّا قَضَى زَيْدٌ مِنْهَا وَطَرًا زَوَّجْنَاكَهَا ﴾ [سورہ احزاب: ۳۷]","’’پس جب زید نے اس عورت سے اپنی غرض پوری کر لی تو ہم نے اسے تیرے نکاح میں دے دیا۔‘‘","نیز اللہ عزوجل کا فرمان ہے:","﴿ وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ ﴾ [سورہ نور: ۳۲]","’’تم میں سے جو مرد عورت بے نکاح کے ہوں ان کا نکاح کر دو۔‘‘","ایک عورت نے کہا: اے اللہ کے رسول! میں آپ کی خدمت میں ہبہ کرتی ہوں، ایک آدمی نے کہا: اس کی شادی مجھ سے کر دیجئے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اس قرآن کے عوض جو تمہیں یاد ہے، میں اس کا نکاح تمہارے ساتھ کرتا ہوں۔‘‘ (صحیح بخاری: ۲۳۱۰)"],"822":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ ﴾ [سورہ نساء: ۳]","’’تو اور عورتوں میں سے جو بھی تمہیں اچھی لگیں تم ان سے نکاح کرو، دو دو، تین تین، چار چار۔‘‘","یعنی دو بیویاں رکھو یا تین یا چار، امام شافعی رحمہ اللہ نے کہا: اللہ تعالیٰ نے آزاد عورتوں کی جو آخری مباح تعداد بیان کی ہے وہ چار کی ہے۔ نبی صلی اللہ علیہ وسلم کے علاوہ کوئی اور شخص بیک وقت چار بیویوں سے زیادہ نہیں رکھ سکتا، اس سے زائد بیویاں رکھنا حرام ہے، آیت کریمہ اس بات پر دلالت کرتی ہے کہ یہ حکم آزاد افراد کے لیے ہے کیونکہ اسی آیت کے اگلے الفاظ","﴿ أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ ﴾ [سورہ نساء: ۳]","’’یا تمہاری ملکیت کی لونڈی۔‘‘","سے پتہ چلتا ہے کہ بیک وقت چار بیویوں کے علاوہ لونڈیاں رکھی جا سکتی ہیں اور لونڈیاں آزاد لوگوں کی ہی ہوتی ہیں غلاموں کی نہیں۔"],"823":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالَاتُكُمْ وَبَنَاتُ الْأَخِ وَبَنَاتُ الْأُخْتِ وَأُمَّهَاتُكُمُ الَّتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ وَأُمَّهَاتُ نِسَائِكُمْ وَرَبَائِبُكُمُ الَّتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ الَّتِي دَخَلْتُمْ بِهِنَّ فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ وَأَنْ تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا ﴾ [سورہ نساء: ۲۳]","’’حرام کی گئیں تم پر مائیں اور تمہاری لڑکیاں اور تمہاری بہنیں، تمہاری پھوپھیاں اور تمہاری خالائیں اور بھائی کی لڑکیاں اور بہن کی لڑکیاں اور تمہاری وہ مائیں جنہوں نے تمہیں دودھ پلایا ہو اور تمہاری دودھ شریک بہنیں اور تمہاری ساس اور تمہاری وہ پرورش کردہ لڑکیاں جو تمہاری گود میں ہیں، تمہاری ان عورتوں سے جن سے تم دخول کر چکے ہو، ہاں اگر تم نے ان سے جماع نہ کیا ہو تو تم پر کوئی گناہ نہیں اور تمہارے صلبی سگے بیٹوں کی بیویاں اور تمہارا دو بہنوں کا جمع کرنا ہاں جو گزر چکا سو گزر چکا، یقیناً اللہ تعالیٰ بخشنے والا مہربان ہے۔‘‘","سیدنا ابن عباس رضی اللہ عنہما نے کہا: نسب کی بنا پر سات رشتے حرام ہیں اور سسرال رشتے بھی حرام ہیں۔ اس کے بعد انہوں نے یہ آیت کریمہ تلاوت کی: ﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ﴾...... [سورہ نساء: ۲۳] (صحیح بخاری: ۵۱۰۵) سیدنا انس رضی اللہ عنہ نے کہا: ﴿وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ﴾ ...... خاوند والی عورتیں مراد ہیں جو آزاد ہوں وہ بھی حرام ہیں اور ﴿وَمَا مَلَكَتْ أَيْمَانُكُمْ﴾...... کا یہ مطلب ہے کہ اگر کسی کی لونڈی اس کے غلام کے نکاح میں ہو تو اس کو غلام سے چھین کر یعنی طلاق دلوا کر خود اپنی بیوی بنا سکتے ہیں۔ سیدنا ابن عباس رضی اللہ عنہما نے کہا: چار بیگمات ہوتے ہوئے پانچویں سے بھی نکاح کرنا حرام ہے، جیسے اپنی ماں، بیٹی بہن سے نکاح کرنا حرام ہے۔ امام بغوی رحمہ اللہ نے کہا: کنیزوں کے بارے میں کوئی تعداد مقرر نہیں، جناب سعید بن جبیر رحمہ اللہ نے سیدنا ابن عباس رضی اللہ عنہما سے نقل کیا ہے کہ انہوں نے اللہ عز و جل کے فرمان: ﴿وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ﴾......(سورہ نساء: ۲۴) کے بارے میں کہا: اس سے مراد وہ لونڈیاں ہیں جو پیچھے شادی شدہ تھیں وہ تمہارے لیے حلال ہیں (استبراء رحم کے بعد)۔"],"824":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَأُمَّهَاتُكُمُ الَّتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ ﴾ [سورہ نساء: ۲۳]","’’اور تمہاری وہ مائیں جنہوں نے تمہیں دودھ پلایا ہو اور تمہاری دودھ شریک بہنیں۔‘‘"],"826":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ ﴾ [سورہ بقرہ: ۲۳۳]","’’اور مائیں اپنے بچوں کو مکمل دو سال دودھ پلائیں۔‘‘"],"836":["سیدہ عائشہ رضی اللہ عنہا نے سیدہ بریرہ رضی اللہ عنہا کے بارے میں کہا: جب وہ آزاد ہو گئی تو اسے اس کے خاوند کے معاملے میں اختیار دیا گیا تھا۔ (صحیح بخاری: ۵۲۸۴، صحیح مسلم: ۱۵۰۴)"],"838":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَآتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً ﴾ [سورہ نساء: ۲۴]","’’انہیں ان کا مقررہ مہر ادا کرو۔‘‘","یہاں لفظ اجر سے مراد حق مہر ہے۔ اللہ عزوجل کا فرمان ہے:","﴿ وَآتُوا النِّسَاءَ صَدُقَاتِهِنَّ نِحْلَةً ﴾ [سورہ نساء: ۴]","’’اور عورتوں کو ان کے مہر راضی خوشی دے دو۔‘‘","اگر کوئی شخص یہ سوال اٹھائے کہ حق مہر تو عورت سے فائدہ اٹھانے کا عوض اور بدل ہوتا پھر اسے آیت مبارکہ میں (نِحْلَة) کیوں کہا گیا جبکہ اس لفظ کے لغوی معنی تحفہ اور ہدیہ دینے کے ہیں جو بلا معاوضہ ہوتا ہے؟ تو جواباً کہا جائے گا کہ یہاں (نِحْلَة) سے مراد دین پر عمل کرنا اور شریعت کے ایک مقرر کردہ حکم کو بصد خوشی پورا کرنا ہے جیسا کہ عربی زبان میں کسی مذہب اور دین کو اختیار کرنے والے کے بارے میں کہا جاتا ہے: ’’فُلَانٌ انْتَحَلَ مَذْهَبَ كَذَا.‘‘ فلاں صاحب نے یہ مذہب اختیار کر لیا ہے یعنی وہ بخوشی اس مذہب کا پیروکار اور متبع بن گیا ہے۔ حق مہر کو (نِحْلَة) کہنے کی ایک وجہ لغوی رعایت بھی ہو سکتی ہے کہ در حقیقت یہ رقم اسے بغیر عوض ہی حاصل ہو رہی ہے، میاں بیوی مباشرت کی لذت اور لطف اندوزی میں برابر کے شریک ہیں، جیسا خاوند مخطوظ ہو رہا ہے ویسے عورت بھی جنسی تسکین کے لمحات سے گزر رہی ہے بلکہ بسا اوقات ایک عورت غلبہ شہوت کی بنا پر زیادہ کیف ونشاط اٹھاتی ہوتی ہے تو اس طرح حق مہر کی رقم اس کیلئے بلا معاوضہ ہی ہے اور تحفہ اور ہدیہ ہی کی حقیقت رکھتی ہے۔ اس سوال کا ایک جواب یہ بھی دیا جا سکتا ہے کہ پہلی شریعتوں میں حق مہر پر اولیاء کا قبضہ تھا، وہ اسے اپنا حق سمجھتے تھے، عورتوں کو کچھ نہیں ملتا تھا جیسا کہ حضرت شعیب علیہ السلام کے الفاظ قرآن مجید میں مذکور ہیں:","﴿ قَالَ إِنِّي أُرِيدُ أَنْ أُنْكِحَكَ إِحْدَى ابْنَتَيَّ هَاتَيْنِ عَلَى أَنْ تَأْجُرَنِي ثَمَانِيَ حِجَجٍ ﴾ [سورہ قصص: ۲۷]","’’اس بزرگ نے کہا: میں اپنی ان دونوں لڑکیوں میں سے ایک کو آپ کے نکاح میں دینا چاہتا ہوں اس (مہر پر) کہ آپ آٹھ سال تک میرا کام کاج کریں۔‘‘","حضرت نے نکاح میں اپنا کام کرنے کی شرط لگائی ہے اپنی بیٹی کا کام کرنے کی نہیں پھر جب اللہ تعالیٰ نے ہماری شریعت میں اسے عورتوں کا حق مہر دیا تو یہ گویا اللہ تعالیٰ کی طرف سے ان کے لیے ایک تحفہ ہوا۔ واللہ اعلم"],"841":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَكَيْفَ تَأْخُذُونَهُ وَقَدْ أَفْضَى بَعْضُكُمْ إِلَى بَعْضٍ ﴾ [سورہ نساء: ۲۱]","’’تم اسے کیسے لے لو گے، حالانکہ تم ایک دوسرے سے مل چکے ہو۔‘‘","ایک قول کے مطابق اس آیت کریمہ کا مطلب ہے تم نے خلوت اختیار کر لی ہے اور یہ بھی کہا گیا ہے کہ اس سے مراد ایک لحاف اور بستر میں لیٹنا ہے۔"],"842":["متعہ سے مراد یہاں فائدہ پہنچانا ہے یعنی جدا ہونے والی عورت کو کچھ نہ کچھ مالی مدد دینا۔ (ع،س)","اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ ﴾ [سورہ بقرہ: ۲۴۱]","’’طلاق والیوں کو اچھی طرح فائدہ دینا پرہیز گاروں پر لازم ہے۔‘‘"],"851":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ ﴾ [سورہ بقرہ: ۲۲۸]","’’اور عورتوں کے بھی ویسے ہی حق ہیں جیسے ان پر مردوں کے ہیں اچھائی کے ساتھ، ہاں مردوں کو عورتوں پر فضیلت ہے۔‘‘","اللہ عز وجل کا فرمان ہے:","﴿ فَالصَّالِحَاتُ قَانِتَاتٌ ﴾ [سورہ نساء: ۳۴]","’’پس نیک فرمانبردار عورتیں۔‘‘","یعنی اپنے شوہروں کے حقوق کی ادائیگی اور نگہداشت کرنے والیاں، القنوت سے مراد قیام ہے یعنی حقوق اور فرائض کا قیام اور (القنوت) کا معنی دعا بھی ہوتا ہے، بعض نے کہا (قَانِتَات) کا معنی ہے نماز پڑھنے والی عورتیں جیسا کہ اللہ عز وجل کے فرمان میں مذکور ہے:","﴿ أَمَّنْ هُوَ قَانِتٌ آنَاءَ اللَّيْلِ سَاجِدًا وَقَائِمًا ﴾ [سورہ زمر: ۹]","’’بلاشبہ وہ شخص راتوں کے اوقات سجدے اور قیام کی حالت میں گزارتا ہے۔‘‘"],"854":["اللہ تعالیٰ کا فرمان ہے:","﴿ وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ ﴾ [نساء: ۱۹]","’’ان کے ساتھ اچھے طریقے سے بود وباش رکھو۔‘‘"],"855":["نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تو اپنی بیوی کو یوں نہ مار پیٹ جس طرح تو اپنی کنیز کو مارتا ہے۔‘‘ (صحیح، ابو داود: ۲۱۴۲)"],"856":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ ﴾ [سورہ نساء: ۳۴]","’’اور جن عورتوں کی نافرمانی اور بد دماغی کا تمھیں خوف ہو انھیں نصیحت کرو اور انھیں الگ بستروں پر چھوڑ دو اور انھیں مار کی سزا دو۔‘‘","﴿نُشُوزَهُنَّ﴾ نافرمانی کرنا اور خاوندوں کی اطاعت سے جسے اللہ کریم نے واجب قرار دیا ہے اس سے سرتابی کرنا، ایک معنی یہ بھی کیا گیا ہے کہ النشوز سے مراد زوجین میں سے ہر ایک کا ایک دوسرے کو ناپسند کرنا ہے۔ جب کوئی عورت اپنے خاوند کو دل سے نہ چاہتی ہو تو کہا جاتا ہے: نشزت المراة تنشز ایسی عورت کو ناشز (بغیر ھا کے) کہا جاتا ہے۔ امام شافعی رحمہ اللہ آیت کریمہ پر تبصرہ کرتے ہوئے کہتے ہیں کہ آیت سے معلوم ہوا کہ عورت سے ایسا اختلاف روا اور جائز ہے جس پر اسے سرزنش کی جاسکتی ہے، ڈانٹا جاسکتا ہے، اور اسے پوچھ گچھ کی جاسکتی ہے۔ خاوند اگر محسوس کرے کہ اس کی بیوی قول و فعل میں تجاوز کی عادی ہو رہی ہے تو اسے زبانی نصیحت کرے، سمجھائے اور وعظ و تلقین سے کام لے، پھر اگر اس کی طرف سے بد دماغی اور بے پروائی کا مظاہرہ ہو تو اس سے بولنا چالنا موقوف کردے، بستر الگ کردے پھر بھی اس کی طبیعت اور مزاج میں فرق نہ پڑے اور وہ دو بدو جواب دینے لگے تو اسے (معمولی) جسمانی سزا دے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَأُحْضِرَتِ الْأَنْفُسُ الشُّحَّ ﴾ [سورہ نساء: ۱۲۸]","’’طمع ہر نفس میں شامل کر دی گئی ہے۔‘‘","شح کا معنی مفاد اور فائدہ جو ہر نفس کو عزیز ہوتا ہے ہر نفس اپنے مفاد میں بخل اور طمع سے کام لیتا ہے، عورت چاہتی ہے کہ میں اپنے خاوند کی محبت کا مرکز بنوں، اس کے دل میں میرا خاص مقام و مرتبہ ہو، اس کی چاہتوں کا محور میری ذات ہی ہو جبکہ یہی مطالبہ خاوند عورت سے رکھتا ہے، خواہ خود خاوند دوسری بیوی کو زیادہ چاہتا ہو مگر اس سے اس کا مطالبہ ہے کہ وہ مجھے کامل توجہ دے۔ یہ باب نصر، ینصر اور ضرب، یضرب دونوں طرح آتا ہے یعنی شَحَّ، یَشُحُ اور یَشِحُ."],"857":["اللہ سبحانہ و تعالیٰ کا فرمان ہے: ﴿وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا﴾ ’’اگر تمھیں میاں بیوی کے درمیان آپس کی ان بن کا خوف ہو تو ایک منصف مرد والوں میں سے اور ایک عورت کے گھر والوں میں سے مقرر کرو۔‘‘ (سورہ نساء: ۳۵) الشِّقَاق سے مراد عداوت اور دشمنی، ان بن اور ناراضی ہے کیونکہ لڑائی جھگڑے میں ہر کوئی ایک کنارے پر کھڑا ہوتا ہے، اپنے موقف پر ڈٹا ہوتا ہو۔ اور کنارے کو عربی زبان میں (شق) کہتے ہیں۔ اسی سے اللہ عزوجل کا فرمان ہے: ﴿فِي عِزَّةٍ وَشِقَاقٍ﴾ ’’بلکہ کفار غرور ومخالفت میں پڑے ہوئے ہیں۔‘‘ (سورہ ص: ۲)"],"859":["اللہ تعالیٰ کا فرمان ہے:","﴿ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ ﴾ [سورہ بقرہ: ۲۲۹]","’’اگر تمھیں ڈر ہو کہ یہ دونوں اللہ کی حدیں قائم نہ رکھ سکیں گے تو عورت رہائی پانے کے لیے کچھ دے ڈالے اس میں دونوں پر گناہ نہیں۔‘‘","امام طاؤس رحمہ اللہ نے کہا: اس آیت کا مطلب یہ ہے کہ دونوں کو اس بات کا اندیشہ ہو کہ اللہ تعالیٰ کے مقرر کردہ حقوق فرائض جو حسن عشرت اور عمدہ صحبت کے حوالے سے دونوں پر عائد ہوتے ہیں ان کو پورا نہ کر سکیں گے۔"],"860":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ﴾ ’’اے مومنو! جب تم مومن عورتوں سے نکاح کرو پھر ہاتھ لگانے سے پہلے (ہی) طلاق دے دو۔‘‘ (سورہ احزاب: ۴۹) سیدنا ابن عباس رضی اللہ عنہما نے کہا: اللہ تعالیٰ نے طلاق کو نکاح کے بعد ذکر کیا ہے، پھر انھوں نے اسی آیت کریمہ کی تلاوت کی۔"],"861":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ ﴾ [سورہ طلاق: ۱]","’’جب تم اپنی بیویوں کو طلاق دینا چاہو تو ان کی عدت (کے دنوں کے آغاز) میں انھیں طلاق دو۔‘‘","سیدنا عبداللہ بن عمر رضی اللہ عنہما نے ان الفاظ کو یوں پڑھا (فَطَلِّقُوهُنَّ لِقُبُلِ عِدَّتِهِنَّ) ’’انھیں عدت کے آغاز میں طلاق دو۔‘‘ (لِعِدَّتِهِنَّ) میں لام توقیت کے لیے ہے یعنی عدت کے آغاز میں طلاق دو (یعنی جب عورت حیض سے پاک ہو جائے تو اس سے ہم بستری کیے بغیر طلاق دو، حالت طہر اس کی عدت کا آغاز ہے) یہ جملہ یوں ہے جیسے آپ کہیں (کُتِبَ لِعَشْرٍ مِنَ الشَّهْرِ) یعنی ہوگا یہ تحریر مہینے کے دس دن گزر جانے کے بعد معرض تحریر میں آئی۔ اسی طرح حیض کے گزر جانے کے بعد حالت طہر میں ہم بستری کیے بغیر طلاق دی جائے۔"],"863":["اللہ سبحانہ و تعالیٰ کا فرمان ہے: ﴿يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا﴾ ’’اے نبی! اپنی بیویوں سے کہہ دو کہ اگر تم دنیا کی زندگی اور زینت چاہتی ہو تو آؤ میں تمھیں کچھ دے دلا دوں اور تمھیں اچھائی کے ساتھ رخصت کر دوں۔‘‘ (سورہ احزاب: ۲۸)"],"865":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ﴾ ’’اے نبی صلی اللہ علیہ وسلم! جس چیز کو اللہ نے آپ کے لیے حلال کر دیا ہے اسے آپ کیوں حرام کرتے ہیں؟ (کیا) آپ اپنی بیویوں کی رضامندی حاصل کرنا چاہتے ہیں اور اللہ بخشنے والا رحم کرنے والا ہے۔‘‘ (سورہ تحریم: ۱)"],"867":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَإِنْ طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ ﴾ [سورہ بقرہ: ۲۳۰]","’’پھر اگر اس کو (تیسری بار) طلاق دے دے تو اب اس کے لیے حلال نہیں جب تک کہ وہ عورت اس کے سوا دوسرے سے نکاح نہ کرے۔‘‘"],"868":["اللہ تعالیٰ کا فرمان ہے:","﴿ لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ﴾ [سورہ بقرہ: ۲۲۶]","’’جو لوگ اپنی بیویوں سے (تعلق نہ رکھنے کی) قسمیں کھائیں، ان کے لیے چار مہینے کی مدت ہے۔‘‘","ایلاء کے معنی قسم کھانے کے ہیں۔ یہ لفظ الیۃ (یاء کی تشدید کے ساتھ) سے مشتق ہے آلٰی فُلانٌ مِنْ اِمْرَأَتِهِ کے معنی ہوں گے: فلاں نے اپنی بیوی کے قریب نہ جانے کی قسم کھا رکھی ہے، یہ لفظ تین ابواب سے مستعمل ہے، آلٰی، (افعال)، تآلٰی (تفعل) اور ابتلی (افتعال) اللہ عزوجل کا فرمان ہے:","﴿ وَلَا يَأْتَلِ أُولُوا الْفَضْلِ مِنْكُمْ ﴾ [سورہ نور: ۲۲]","’’تم میں سے جو بزرگی اور کشادگی والے ہیں انھیں قسم نہیں کھا لینی چاہیے۔‘‘","اور اس آیت کریمہ کو ’’ولا يتأل‘‘ بھی پڑھا گیا ہے۔"],"869":["اللہ تعالیٰ کا فرمان ہے:","﴿ الَّذِينَ يُظَهِّرُونَ مِنْكُمْ مِنْ نِسَائِهِمْ مَا هُنَّ أُمَّهَاتِهِمْ إِنْ أُمَّهَاتُهُمْ إِلَّا اللَّائِي وَلَدْنَهُمْ وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا ﴾ [سورہ مجادلہ: ۲]","’’تم میں سے جو لوگ اپنی بیویوں سے ظہار کرتے ہیں (یعنی انھیں ماں کہہ بیٹھتے ہیں) وہ دراصل ان کی مائیں نہیں بن جاتیں، ان کی مائیں تو وہی ہیں جن کے بطن سے وہ پیدا ہوئے، یقیناً یہ لوگ ایک نامعقول اور جھوٹی بات کہتے ہیں۔‘‘","لفظ زور سے مراد جھوٹ ہے، اس کو زور کہنے کی وجہ یہ ہے کہ یہ بات حق وصواب سے بہت ہٹی ہوئی ہے اور زور کے لغوی معنی یہی ہیں، جیسے اللہ عزوجل کا فرمان ہے:","﴿ تَزَاوَرُ عَنْ كَهْفِهِمْ ﴾ [سورہ کہف: ۱۷]","’’آفتاب ان کے غار سے دائیں جانب کو جھک جاتا ہے۔‘‘","یعنی دوسری جانب مائل ہو جاتا ہے۔ اللہ تعالیٰ کا فرمان ہے:","﴿ وَالَّذِينَ يُظَهِّرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا ﴾ [سورہ مجادلہ: ۳]","’’جو لوگ اپنی بیویوں سے ظہار کریں، پھر اپنی کہی ہوئی بات سے رجوع کرلیں تو ان کے ذمہ آپس میں ایک دوسرے کو چھونے سے پہلے ایک غلام آزاد کرنا ہے۔‘‘"],"871":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ وَالْخَامِسَةُ أَنَّ لَعْنَتَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ وَيَدْرَؤُا عَنْهَا الْعَذَابَ أَنْ تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ ﴾ [سورہ نور: ۶ تا ۹]","’’جو لوگ اپنی بیویوں پر بدکاری کی تہمت لگائیں اور ان کا کوئی گواہ سوائے خود ان کی ذات کے نہ ہو تو ایسے لوگوں میں سے ہر ایک کا ثبوت یہ ہے کہ چار مرتبہ اللہ کی قسم کھا کر کہے کہ وہ بچوں میں سے ہے، اور پانچویں مرتبہ کہے کہ اس پر اللہ تعالیٰ کی لعنت ہو اگر وہ جھوٹوں میں سے ہو، اور عورت سے سزا اس طرح دور ہو سکتی ہے کہ وہ چار مرتبہ اللہ کی قسم کھا کر کہے کہ یقیناً اس کا مرد جھوٹ بولنے والوں میں سے ہے، اور پانچویں دفعہ کہے کہ اس پر اللہ تعالیٰ کا غضب ہو اگر اس کا خاوند بچوں میں سے ہو۔‘‘"],"877":["امام بغوی رحمہ اللہ نے کہا: قیافہ شناس یعنی کھوجی کو عربی زبان میں القائف کہنے کی وجہ یہ ہے کہ وہ آثار اور نشانات قدم وغیرہ کی پیروی کرتا اور ٹوہ لگاتا ہے اور اس لفظ کے لغوی معنی یہی ہیں۔ دیکھیے یہ لفظ اللہ سبحانہ وتعالیٰ کے فرمان میں مذکور ہے: ﴿وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ......﴾ ’’جس بات کی تجھے خبر نہ ہو اس کے پیچھے نہ پڑ‘‘ (سورہ الاسراء: ۳۶) یعنی پیچھے مت پڑو۔ قفوتہ، اقفوہ، وقفتہ، اقوفہ اور قفیتہ ان تمام الفاظ کے معنی ہیں پیچھے لگنا، کسی کی ٹوہ لگانا اور نشانات قدم کی پیروی کرنا۔"],"879":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُّبَيِّنَةٍ﴾ ’’نہ تم انہیں ان کے گھر سے نکالو اور نہ ہو (خود) نکلیں ہاں یہ بات ہے کہ وہ کھلی برائی کر بیٹھیں۔‘‘ (سورہ طلاق: ۱) اللہ عزوجل کا فرمان ہے: ﴿أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِنْ وُجْدِكُمْ......﴾ ’’تم اپنی طاقت کے مطابق جہاں تم رہتے ہو وہاں ان (طلاق والی) عورتوں کو رکھو۔‘‘ (سورہ طلاق: ۶) لفظ الوَجْد اور الجِدَة جب مال کے لیے بولے جائیں تو ان کے معنی فراخی والا ہونا، صاحب حیثیت ہونا اور مال و دولت والا ہونا ہوتے ہیں۔ مالدار اور توانگر شخص کو رجل واجد کہتے ہیں۔ یہ لفظ الوجد اور الجدة سے ماخوذ ہے۔ وَجَدَ الضَّالَّةَ وَجْدَانًا کا معنی ہے اسے گم شدہ چیز مل گئی۔ جب حاکم وقت کسی کی محبت میں سرشار ہو تو کہا جاتا ہے: وَجَدَ السُّلْطَانُ عَلَيْهِ وَجْدًا ومَوْجِدَةً. اور اگر کوئی شخص کسی عورت کی محبت میں گرفتار ہو تو اہل عرب کہتے ہیں: فُلَانٌ يَجِدُ بِفُلَانَةَ وَجْدًا."],"880":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَإِنْ كُنَّ أُولَاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ......﴾ ’’اور اگر وہ حمل سے ہوں تو جب تک بچہ پیدا ہو لے انہیں خرچ دیتے رہا کرو۔‘‘ (سورہ طلاق: ۶)"],"886":["ام ولد سے مراد وہ لونڈی ہے جس سے مالک کی اولاد ہو جائے اور استبراء سے مراد یہ معلوم کرنا ہے کہ آیا اس کا رحم خالی ہے۔ (ع،س)"],"888":["اللہ تعالیٰ کا فرمان ہے: ﴿لِيُنْفِقْ ذُو سَعَةٍ مِنْ سَعَتِهِ وَمَنْ قُدِرَ عَلَيْهِ رِزْقُهُ فَلْيُنْفِقْ مِمَّا آتَاهُ اللهُ......﴾ ’’کشادگی والے کو اپنی کشادگی سے خرچ کرنا چاہیے اور جس پر اس کے رزق کی تنگی کی گئی ہو اسے چاہیے کہ جو کچھ اللہ تعالیٰ نے اسے دے رکھا ہے اسی میں سے (حسب حیثیت) دے۔‘‘ (سورہ طلاق: ۷) نیز اللہ جل ذکرہ کا فرمان ہے: ﴿ذَلِكَ أَدْنَى أَلَّا تَعُولُوا......﴾ ’’یہ زیادہ قریب ہے کہ (ایسا کرنے سے نا انصافی اور) ایک طرف جھک پڑنے سے بچ جاؤ۔‘‘ (سورہ نساء: ۳) امام شافعی رحمہ اللہ نے کہا: اس آیت کا مطلب ہے کہ تم اپنے اوپر ایسے افراد کی کثرت نہ کرو جن کی ضروریات زندگی تمہیں فراہم کرنا پڑیں اور ان کی عیال داری کا بار برداشت کرنا پڑے۔ اس آیت سے پتہ چلا کہ بیوی کا خرچہ مرد کے ذمے ہے۔ امام کسائی نے کہا: جب کسی شخص کے بال بچے زیادہ ہوں تو اس کیفیت کو عَالَ الرَّجُلُ يَعُولُ کے الفاظ سے بیان کیا جاتا ہے جبکہ ان معانی کے حصول کے لیے عمدہ اور نفیس لغت لفظ اعال کا استعمال ہے، عَالَ يَعُولُ کا معنی ہے ظلم کرنا اور عَالَ يَعِيلُ کا معنی ہے فقیر اور مفلس و قلاش ہونا۔ اللہ عزوجل کا فرمان ہے: ﴿ذَلِكَ أَدْنَى أَلَّا تَعُولُوا﴾ ’’یہ زیادہ قریب ہے کہ تم ظلم و ستم نہ کرو۔‘‘ اور ان لَا تَعُولُوا کا ایک معنی یہ بھی کیا گیا ہے کہ تم بیویوں کو ٹالتے نہ رہو۔ سیدنا جابر بن عبداللہ رضی اللہ عنہما نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کے خطبہ میں ارشاد فرمایا: ’’(اے مردو!) تمہارے ذمے ان عورتوں کا نان ونفقہ اور لباس ہے معروف کے مطابق۔‘‘ (صحیح مسلم: ۱۲۱۸) امام شافعی رحمہ اللہ نے کہا: قرآن و سنت میں اس بات کی صراحت ہے کہ ایک مرد کے ذمے اپنی بیوی کا ناگزیر نان ونفقہ اور لباس کی فراہمی فرض ہے، اس کے بغیر کوئی چارہ نہیں، اسی طرح ضروری علاج معالجہ بھی ہے، جس سے انسانی صحت برقرار رہے۔ امام شافعی رحمہ اللہ نے کہا: خرچے کی دو قسمیں ہیں (۱) تنگ دست کا خرچہ (۲) خوشحال کا خرچہ۔ تنگ دست شخص پر لازم ہے کہ وہ اپنے علاقے کا عمومی کھایا جانے والا غلہ ایک مد نبی اکرم صلی اللہ علیہ وسلم کے دور کے پیمانے کے اعتبار سے اپنی بیوی اور اس کے خادم کو ادا کرے۔ اسی طرح ایک مکیال اپنے شہر کے اعتبار سے بطور سالن روغن زیتون یا گھی وغیرہ ادا کرے نیز بقدر ضرورت کم از کم سرسوں کا تیل اور کنگھی پٹی (شیمپو وغیرہ) کا سامان دینا واجب ہے لیکن یہ چیز عورت کی خدمت گزار کو ادا کرنا واجب نہیں، اس طرح ہر آٹھویں دن رطل گوشت بھی ادا کرے، اور شہر کے معیار کو سامنے رکھتے ہوئے ایک تنگ دست آدمی کے لحاظ سے موسم سرما و گرما کا لباس دینا بھی فرض ہے۔ خوشحال اور کشادہ دست شوہر کے لیے واجب ہے کہ ہر روز دو مد غلہ نیز تنگ دست سے دوگنا سالن اور گوشت کی فراہمی واجب ہے، اسی طرح تیل اور سامان آرائش و زیبائش (میک اپ) کی ادائیگی لازم ہے، اسی طرح بیوی کے خدمت گزار اور نوکر کے لیے ایک مد اور دو تہائی مد غلہ ادا کرے، غلے میں کم از کم مقدار مد مقرر کرنے کی وجہ یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان المبارک میں بحالت روزہ میاں بیوی کے تعلق کو قائم کرنے والے شخص کو ایک ٹوکرہ تھمایا تھا جس میں پندرہ صاع کھجوریں تھیں اور یہ پندرہ صاع کھجور میں ساٹھ مساکین کا کھانا تھا، (جو کہ فی مسکین ایک مد بنتا ہے) اور زیادہ سے زیادہ مقدار دو مد مقرر کرنے کی وجہ یہ ہے کہ نبی صلی اللہ علیہ وسلم نے حالت احرام میں سرمنڈوانے والے کو فی مسکین دو مد غلہ ادا کرنے کا حکم صادر فرمایا اور یہ فدیہ جات میں سب سے زیادہ مقدار ہے اور متوسط پر ایک مد اور ایک نصف مد ہے، یعنی تنگ دست اور خوشحال شخص کی درمیانی مقدار اور بیوی کے خادم کے لیے ایک مد غلہ ہے، یہ امام شافعی رحمہ اللہ کا کلام اور ان کے مذہب کی تفصیل ہے۔"],"889":["اللہ عزوجل کا فرمان ہے: ﴿وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ......﴾ ’’اور جن کے بچے ہیں ان کے ذمے ان کا روٹی کپڑا ہے جو مطابق دستور کے ہو۔‘‘ (سورہ بقرہ: ۲۳۳) خاوند پر عورت کی روٹی کپڑے کی یہ ذمہ داری بچوں کے سبب سے ہے، اللہ عزوجل کا فرمان ہے: ﴿وَإِنْ أَرَدْتُمْ أَنْ تَسْتَرْضِعُوا أَوْلَادَكُمْ......﴾ ’’اور اگر تمہارا ارادہ اپنی اولاد کو دودھ پلوانے کا ہو تو بھی تم پر کوئی گناہ نہیں جب کہ تم ان کو دستور کے مطابق جو دینا ہو وہ ان کے حوالے کر دو۔‘‘ (سورہ بقرہ: ۲۳۳) یعنی تم اپنے بچوں کے لیے دودھ پلانے والی تلاش کرو تو اس کا معاوضہ دستور کے مطابق ادا کر دیا جائے۔"],"896":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿فَكُّ رَقَبَةٍ......﴾ ’’کسی گردن (غلام لونڈی) کو آزاد کرنا۔‘‘ (سورہ بلد: ۱۳) نیز اللہ تعالیٰ کا ارشاد ہے: ﴿فَلَا اقْتَحَمَ الْعَقَبَةَ......﴾ ’’سو اس سے نہ ہو سکا کہ گھاٹی میں داخل ہوتا۔‘‘ (سورہ بلد: ۱۱) یعنی اس نے دنیا میں کوئی گھائی عبور نہیں کی، اس کی وضاحت یہ ہے کہ عقبہ گھائی کو کہتے ہیں یعنی وہ راستہ جو پہاڑ میں ہو، یہ عام طور پر نہایت دشوار گزار ہوتا ہے، مطلب یہ ہے کہ اس نے اللہ کی اطاعت اور بندگی میں نیز نیکی کے کاموں میں کوئی محنت و مشقت نہیں کی جیسے گھائی پر چڑھنے کے لیے سخت جد جہد کی ضرورت ہوتی ہے، پھر گھاٹی میں داخل ہونے کی تفسیر اللہ عزوجل کے اس فرمان میں ہے: ﴿فَكُّ رَقَبَةٍ أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ......﴾ ’’کسی گردن کو آزاد کرنا، یا بھوک والے دن کھانا کھلانا۔‘‘ (سورہ بلد: ۱۳،۱۴) امام زہری رحمہ اللہ نے کہا: یعنی اس نے کوئی دشوار گزار گھائی عبور نہیں کی اور اس کا عبور کرنا، کسی گردن کو آزاد کرنا ہے، مراد یہی ہے کہ دشوار گزار گھائی میں داخل ہونا گردن کو آزاد کرنے سے ہو گا۔"],"901":["مدبر غلام اسے کہتے ہیں جس کا مالک اسے کہہ دے: تو میری وفات کے بعد آزاد ہے۔ (ع،س)"],"902":["ام ولد وہ لونڈی جس کا مالک اس سے ہم بستری کرے اور اس سے اولاد ہو جائے تو وہ آزاد ہو جاتی ہے۔ (ع،س)"],"903":["مکاتب ایسے غلام کو کہتے ہیں جس سے مخصوص معاوضے کے بدلے آزادی کا معاہدہ ہو۔ (ع،س) اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا......﴾ ’’تمہارے غلاموں میں سے جو کوئی کچھ تمہیں دے کر آزادی کی تحریر کرانی چاہے تو تم اسی تحریر انہیں کر دیا کرو اگر تمہیں ان میں کوئی بھلائی نظر آتی ہو۔‘‘ (سورہ نور: ۳۳) امام مجاہد اور عطاء نے کہا: خیر سے مراد مال ہے، ابن جریج نے کہا: میں نے عطاء بن ابی رباح رحمہ اللہ سے پوچھا: کیا اگر مجھے معلوم ہو جائے کہ میرے غلام کے پاس مال ہے اور وہ مکاتب بننا چاہتا ہے تو کیا مجھ پر واجب ہو جائے گا کہ میں اس سے مکاتبت کر لوں؟ انہوں نے کہا کہ میرا خیال تو یہی ہے کہ (ایسی حالت میں کتابت کا معاملہ) واجب ہو جائے گا۔ عمرو بن دینار نے بیان کیا کہ میں نے عطاء سے پوچھا: کیا آپ اس سلسلے میں کسی سے روایت بھی بیان کرتے ہیں؟ تو انہوں نے جواب دیا: نہیں۔ (پھر انہیں یاد آیا) اور مجھے انہوں نے خبر دی کہ موسیٰ بن انس نے انہیں خبر دی کہ سیرین (ابن سیرین رحمہ اللہ کے والد) نے سیدنا انس رضی اللہ عنہ سے مکاتب ہونے کی درخواست کی (یہ سیدنا انس رضی اللہ عنہ کے غلام تھے) جو مالدار بھی تھے لیکن سیدنا انس رضی اللہ عنہ نے انکار کیا، اس پر سیرین سیدنا عمر رضی اللہ عنہ کی خدمت میں حاضر ہوئے، سیدنا عمر رضی اللہ عنہ نے سیدنا انس رضی اللہ عنہ سے فرمایا کتابت کا معاملہ کر لے، انہوں نے پھر انکار کیا تو سیدنا عمر رضی اللہ عنہ نے انہیں درے سے مارا اور یہ آیت پڑھی: ﴿فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا......﴾ ’’اگر تم کو ان میں بھلائی نظر آتی ہو تو ان سے مکاتبت کر لو۔‘‘ چنانچہ سیدنا انس رضی اللہ عنہ نے کتابت کا معاملہ کر لیا۔ امام شافعی رحمہ اللہ نے کہا: ’’بھلائی نظر آنے‘‘ کا واضح اور ظاہر معنی غلام کے بارے میں اور مکاتبت کے سلسلہ میں یہ ہے کہ اس میں کمائی کرنے کا ملکہ ہو، نیز وہ صدق و امانت کے وصف سے متصف ہو، اگر کسی غلام میں یہ اوصاف ہوں تو مجھے یہی بات پسند ہے کہ اس کے ساتھ مکاتبت کرنے سے گریزاں نہ ہوا جائے۔"],"905":["سیدنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ یمین اللہ کے ناموں میں سے ایک نام ہے۔ بعض اہل علم کا کہنا ہے کہ قسم کو یمین کہا جاتا ہے۔ اور اس کا لغوی معنی ’’دایاں ہاتھ‘‘ ہے۔ عرب لوگ بات کو اور سودے یا عہد کو پکا کرنے کے لیے اپنا دایاں ہاتھ فریق ثانی کے ہاتھ پر رکھتے تھے۔ (چونکہ قسم بھی بات کو پختہ کرنے کے لیے ہوتی ہے اس لیے کبھی قسم پر بھی اپنا ہاتھ دوسرے کے ہاتھ پر رکھتے تھے، اس مناسبت سے قسم کو بھی یمین کہا جاتا ہے، (ع، س)۔ قسم کھاتے وقت وَايْمُنُ اللہ کہا کرتے تھے اور بعض نون کو حذف کر دیتے تھے اور وَايْمُ اللہ کہا کرتے تھے۔"],"907":["اللہ تعالیٰ کا فرمان ہے:","﴿ لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ ﴾ [سورہ بقرہ: ۲۲۵]","’’اللہ تمہیں تمہاری ان لغو قسموں پر نہ پکڑے گا۔‘‘"],"908":["اللہ سبحانہ وتعالیٰ کا فرمان:","﴿ وَلَا تَجْعَلُوا اللَّهَ عُرْضَةً لِأَيْمَانِكُمْ أَنْ تَبَرُّوا ﴾ [سورہ بقرہ: ۲۲۴]","’’اور اللہ تعالیٰ کو اپنی قسموں کا اس طرح نشانہ نہ بناؤ کہ بھلائی چھوڑ بیٹھو۔‘‘","زہری رحمہ اللہ نے کہا:","﴿ عُرْضَةً لِأَيْمَانِكُمْ ﴾","’’اپنی قسموں کو نشانہ نہ بناؤ۔‘‘","کا مطلب ہے کہ ان کو نیکی کرنے کے لیے آڑ اور رکاوٹ نہ بناؤ یعنی غصے میں اس طرح قسم مت کھاؤ کہ میں فلاں کے ساتھ نیکی نہیں کروں گا، فلاں سے نہیں بولوں گا، فلاں کے درمیان صلح نہیں کراؤں گا۔ لفظ عُرْضَةٌ اعترض سے ہے، جس کے معنی رکاوٹ کے ہیں جو چیز بھی آپ کے ارادوں کی تکمیل میں سد راہ بنے اس کے لیے عربی زبان میں (اعْتَرَضَ) اور (تَعَرَّضَ) کا لفظ بولا جاتا ہے۔ اصل میں اس لفظ کا محل یہ ہے کہ ایک چالو راستے میں کوئی رکاوٹ درپیش آ جائے جس سے گزرنے والوں کے لیے مشکل بن جائے تو ایسے موقع پر یہ لفظ بولا جاتا ہے۔ بعض کے نزدیک لفظ عُرْضَةٌ خیر اور شر دونوں کے راستے روکنے کے لیے بولا جاتا ہے۔ مطلب یہ ہے کہ قسم کھا کر بھلائی اور پرہیزگاری کے کاموں سے کنارہ کشی اختیار نہ کرو کہ جب نیکی کرنے کا موقع آئے تو کہو کہ میں نیکی نہیں کر سکتا، اس لیے کہ میں نے نیکی نہ کرنے کی قسم اٹھا رکھی ہے اور اس طرح ہر موقع پر جان چھڑا لو۔"],"911":["اللہ تعالیٰ کا فرمان ہے:","﴿ يُوفُونَ بِالنَّذْرِ ﴾ [سورہ دہر: ۷]","’’وہ نذر کو پورا کرتے ہیں۔‘‘"],"918":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ ﴾ [سورہ نساء: ۵۹]","’’فرمانبرداری کرو اللہ تعالیٰ کی اور فرمانبرداری کرو رسول اللہ صلی اللہ علیہ وسلم کی اور تم میں سے اختیار والوں کی۔‘‘","سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: اولوالامر سے مراد امراء وحکام ہیں اور مجاہد رحمہ اللہ نے کہا: اس سے مراد علماء وفقہاء ہیں۔"],"922":["رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «يَا عَبْدَ الرَّحْمَنِ بْنَ سَمُرَةَ لَا تَسْأَلِ الْإِمَارَةَ، فَإِنَّكَ إِنْ أُوتِيتَهَا عَنْ مَسْأَلَةٍ، وُكِلْتَ إِلَيْهَا»...... ’’اے عبدالرحمن! تو امارت کا سوال نہ کرنا، کیونکہ اگر تجھے یہ امارت سوال کی بنا پر مل گئی تو تجھے اس کے سپرد کر دیا جائے گا۔‘‘ (صحیح مسلم: ۱۶۵۲)"],"924":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ ﴾ [سورہ مائدہ: ۸]","’’کسی قوم کی عداوت تمہیں خلاف عدل پر آمادہ نہ کر دے، عدل کیا کرو جو پرہیز گاری کے زیادہ قریب ہے۔‘‘","﴿وَلَا يَجْرِمَنَّكُمْ﴾.... کا معنی ہے تمہیں برانگیختہ نہ کرے اور نہ ابھارے‘‘ اللہ سبحانہ وتعالیٰ نے فرمایا:","﴿ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ ﴾ [سورہ مائدہ: ۴۲]","’’بلاشبہ اللہ انصاف کرنے والوں کو پسند کرتا ہے۔‘‘","المقسط سے مراد عدل وانصاف کرنے والا اور القسط سے مراد عدل وانصاف ہے۔ اللہ عزوجل کا فرمان ہے:","﴿ قُلْ أَمَرَ رَبِّي بِالْقِسْطِ ﴾ [سورہ اعراف: ۲۷]","’’آپ کہہ دیجیے کہ میرے رب نے حکم دیا ہے انصاف کا۔‘‘","یعنی عدل کا حکم دیا ہے، جب یہ لفظ باب افعال سے ہو یعنی اقسط تو معنی ہوتا ہے اس نے عدل کیا اور اگر مجرد کے طور پر استعمال ہو یعنی قسط تو معنی ہوگا اس نے ظلم وجور کیا اور القاسط کا معنی ہے ظلم وستم کرنے والا، اللہ سبحانہ وتعالیٰ نے فرمایا:","﴿ وَأَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَبًا ﴾ [سورہ جن: ۱۵]","’’اور جو ظالم ہیں وہ جہنم کا ایندھن بن گئے۔‘‘","نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’سات قسم کے آدمی ایسے ہیں جنہیں اللہ تعالیٰ اپنے سائے میں جگہ دے گا: ان میں سے ایک عادل حکمران ہے۔‘‘ (صحیح بخاری: ۱۴۲۳، ۶۶۰، صحیح مسلم: ۱۰۳۱)"],"927":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَمَا يَجْحَدُ بِآيَاتِنَا إِلَّا كُلُّ خَتَّارٍ كَفُورٍ ﴾ [لقمان: ۳۲]","’’اور ہماری آیتوں کا انکار صرف وہی کرتے ہیں جو بد عہد اور ناشکرے ہوں۔‘‘","الختر سے مراد دھوکہ ہے۔ بعض کے نزدیک اختر سے مراد وہ فتنہ و فساد اور جنگ وجدال کی کیفیت ہے جو بغاوت اور عذر کے موقع پر بن جاتی ہے اور ہر طرف اندھیر نگری مچی ہوتی ہے۔"],"931":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً ﴾ [سورہ بقرہ: ۳۰]","’’میں زمین میں خلیفہ بنانے والا ہوں۔‘‘","نیز اللہ جل ذکرہ کا فرمان ہے:","﴿ وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ ﴾ [النور: ۵۵]","’’تم میں سے ان لوگوں سے جو ایمان لائے ہیں اور نیک اعمال کیے ہیں اللہ تعالیٰ وعدہ فرما چکا ہے کہ انہیں ضرور زمین میں خلیفہ بنائے گا۔‘‘"],"933":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَلَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ وَتُدْلُوا بِهَا إِلَى الْحُكَّامِ ﴾ [سورہ بقرہ: ۱۸۸]","’’اور ایک دوسرے کا مال ناحق نہ کھایا کرو، نہ حاکموں کو رشوت پہنچایا کرو۔‘‘","یعنی کسی دوسرے کا حق مارنے کے لیے کسی حاکم، قاضی یا اہلکار کو کچھ دینا رشوت اور حرام ہے تا کہ فیصلے میں اپنی مرضی کی تبدیلی کی جائے۔ یہ لفظ ادلیت الدلو ’’میں نے ڈول ڈالا‘‘ سے ماخوذ ہے۔ جب کوئی شخص اپنی حجت اور دلیل کو پوری طرح وضاحت کے ساتھ بیان کر لے تو کہا جاتا ہے: أَدْلَى بِحُجَّتِهِ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ يَأْخُذُونَ عَرَضَ هَذَا الْأَدْنَى ﴾ [سورہ اعراف: ۱۶۹]","’’وہ اس دنیائے فانی کا مال متاع لے لیتے ہیں۔‘‘","یعنی فیصلوں میں من مرضی کی تبدیلی کے لیے رشوت دیتے ہیں۔"],"936":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَهُوَ أَلَدُّ الْخِصَامِ ﴾ [سورہ بقرہ: ۲۰۴]","’’حالانکہ وہ زبردست جھگڑالو ہے۔‘‘","نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’چار باتیں جس کے اندر پائی جائیں وہ منافق ہے (ان میں سے ایک یہ ہے کہ) جب جھگڑا کرے تو گالی گلوچ کرے۔‘‘ (صحیح بخاری: ۳۴، صحیح مسلم: ۵۸)"],"937":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ تِلْكَ أَمَانِيُّهُمْ قُلْ هَاتُوا بُرْهَانَكُمْ إِنْ كُنْتُمْ صَادِقِينَ ﴾ [سورہ بقرہ: ۱۱۱]","’’یہ صرف ان کی آرزوئیں ہیں، ان سے کہو کہ اگر تم سچے ہو تو کوئی دلیل پیش کرو۔‘‘","مدعی کا معنی ہے: تمنا کرنے والا۔ یعنی محض آرزوئیں جو دلیل کی محتاج ہیں۔ اللہ عزوجل کا ارشاد گرامی ہے:","﴿ وَلَهُمْ مَّا يَدَّعُونَ ﴾ [یس: ۵۷]","’’اور جو بھی کچھ وہ طلب کریں۔‘‘","یعنی وہ جو بھی آرزو کریں گے ان کی وہ آرزو پوری کی جائے گی، اہل عرب کہتے ہیں: اِدْعُ عَلَى مَا شِئْتَ ’’تو جو مجھ سے فرمائش کر سکتا ہے کر لے۔‘‘ اللہ سبحانہ وتعالیٰ کا فرمان جو سیدنا داؤد علیہ السلام کے متعلق ہے:","﴿ وَآتَيْنَهُ الْحِكْمَةَ وَفَصْلَ الْخِطَابِ ﴾ [ص: ۲۰]","’’اور ہم نے اسے حکمت دی تھی اور بات کا فیصلہ کرنا۔‘‘","اس کی بابت کہا گیا ہے کہ اس سے مراد ہے کہ دلیل دینا مدعی کے ذمے لازم ہے اور قسم کھانا مدعی علیہ پر ہے۔ بعض کے نزدیک اس سے مراد مقدمات کے فیصلے کرنے کی صورت حق وباطل کے درمیان امتیاز کرنے کی بصیرت، تفقہ استدلال اور بیان کی قوت ہے۔"],"941":["اس عنوان کا مقصد یہ اہم مسئلہ بیان کرنا ہے کہ قاضی اور حج ظاہری دلائل کے مطابق فیصلہ کرتے ہیں۔ اس لیے اگر کسی قاضی یا حاکم وغیرہ نے غلط فیصلہ کر دیا تو غلط ہی ہوگا اور ناجائز بھی۔ کسی شخص کے ناجائز فیصلہ کرنے سے وہ فیصلہ شرعی طور پر جائز قرار نہیں پاتا اور نہ اس کے فیصلے سے کوئی حرام کام حلال قرار پائے گا اور نہ حلال کام حرام ہی ہو گا بلکہ اس کا وبال غلط دلائل مہیا کرنے والے کے سر پر ہوگا۔ (ع، س)"],"943":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَرَجُلٌ وَامْرَأَتَانِ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَدَاءِ ﴾ [سورہ بقرہ: ۲۸۲]","’’ایک مرد اور دو عورتیں جنہیں تم گواہوں میں سے پسند کرلو۔‘‘","اللہ عزوجل کا فرمان ہے:","﴿ وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ ﴾ [سورہ طلاق: ۲]","’’اور آپس میں سے دو عادل شخصوں کو گواہ کرلو۔‘‘","اللہ سبحانہ وتعالیٰ نے فرمایا:","﴿ إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا ﴾ [سورہ حجرات: ۶]","’’اگر تمہیں کوئی فاسق خبر دے تو تم اس کی اچھی طرح تحقیق کر لیا کرو۔‘‘"],"947":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ ﴾ [بنی اسرائیل: ۳۳]","’’اور کسی جان کو جس کا مارنا اللہ نے حرام کر دیا ہے ہرگز ناحق قتل نہ کرنا۔‘‘","جناب سعید بن جبیر رحمہ اللہ نے کہا: کہ انہوں نے سیدنا ابن عباس رضی اللہ عنہما سے اللہ عزوجل کے فرمان: ﴿فَجَزَاؤُهُ جَهَنَّمُ﴾ ’’اس کی سزا جہنم ہے۔‘‘ (سورہ نساء: ۹۳) کی بابت پوچھا تو انہوں نے کہا: اس کی توبہ قبول نہیں۔ اور ان سے اللہ عزوجل کے فرمان: ﴿وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ﴾ ’’اور اللہ کے ساتھ کسی دوسرے معبود کو نہیں پکارتے۔‘‘ (الفرقان: ۶۷) سیدنا ابن عباس رضی اللہ عنہما نے کہا: امام مجاہد رحمہ اللہ نے اللہ سبحانہ وتعالیٰ کے فرمان: ﴿فَجَزَاؤُهُ جَهَنَّمُ﴾ کے متعلق کہا: ماسوائے اس شخص کے جو نادم اور پشیمان ہوا (اور توبہ کر لی) اور اللہ عزوجل نے فرمایا:","﴿ إِنَّ قَتْلَهُمْ كَانَ خِطْئًا كَبِيرًا ﴾ [الاسراء: ۳۱]","’’یقیناً ان کا قتل کرنا کبیرہ گناہ ہے۔‘‘","کہا گیا ہے کہ اس آیت کریمہ میں لفظ خِطْئًا، أَخْطَأَ کے معنی میں ہے۔ امام ازہری رحمہ اللہ نے کہا: لفظ الخطیئۃ اور الخطا دونوں کے معنی گناہ کے ہیں۔ یہ بھی منقول ہے کہ لفظ خطی اس وقت بولا جاتا ہے جب کوئی کام جان بوجھ کر کیا جائے اور لفظ خطا اس وقت بولا جاتا ہے جب کوئی کام بغیر قصد اور ارادہ کے کیا جائے۔ لفظ الخطاء اسم ہے، جو لفظ الْإِخْطَاء کے معنی میں استعمال ہوتا ہے اور اس کا معنی ہے: غلطی یعنی صحیح اور صواب کا الٹ۔ اس کو دو طرح پڑھا گیا ہے۔ قصر کے ساتھ اور یہ عمدہ قراءت ہے، مد کے ساتھ اور اس طرح پڑھنا بہت کم ہے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَالْمُؤْتَفِكَتُ بِالْخَاطِئَةِ ﴾ [سورہ حاقہ: ۹]","’’اور جن کی بستیاں الٹ دی گئیں، انہوں نے بھی خطائیں کیں۔‘‘","یعنی انہیں ایک بڑی غلطی کے عوض پکڑ لیا گیا۔ یہاں لفظ الْخَاطِئَةُ مصدر کے معنی میں ہے جو فاعلہ کے وزن پر ہے۔ نبی اکرم صلی اللہ علیہ وسلم کا فرمان ہے: «الْكَبَائِرُ: الْإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَتْلُ النَّفْسِ، وَالْيَمِينُ الْغَمُوسُ»...... ’’کبیرہ گناہوں میں سے ہے: اللہ کے ساتھ شرک کرنا، والدین کی نافرمانی کرنا، کسی جان کو قتل کرنا اور جھوٹی قسم اٹھانا۔‘‘ (صحیح بخاری: ۶۶۷۵)"],"950":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى ﴾ [سورہ بقرہ: ۱۷۸]","’’اے ایمان والو! تم پر مقتولوں کا قصاص لینا فرض کیا گیا ہے۔‘‘","سیدنا ابن عباس رضی اللہ عنہما نے کہا: بنی اسرائیل پر قصاص لینے کا ہی حکم تھا، دیت وصول کرنے کی رخصت نہ تھی، لیکن اللہ تعالیٰ نے اس امت کے لیے یہ حکم نازل فرمایا:","﴿ كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثَى بِالْأُنْثَى فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ ﴾ [سورہ بقرہ: ۱۷۸]","’’تم پر مقتولوں کا قصاص لینا فرض کیا گیا ہے، آزاد کے بدلے آزاد، غلام کے بدلے غلام، عورت کے بدلے عورت، ہاں جس کسی کو اس کے بھائی کی طرف سے کچھ معافی دے دی جائے۔‘‘","یعنی دیت وصول نہ کی جائے اور اسے معاف کر دیا جائے۔ عفو یہ ہے کہ قتل عمد میں دیت قبول کرلی جائے اور قصاص ترک کر دیا جائے۔ کہا گیا ہے کہ اللہ عز وجل کے فرمان","﴿ فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ ﴾","’’جس کو اس کے بھائی کے مال سے دیا جائے۔‘‘","کا مطلب ہے جسے اپنے بھائی کے مال سے دیا جائے یعنی قاتل کے مال سے دیت دی جائے۔ (اسلامی اخوت کے پیش نظر قاتل کو بھائی کہا گیا ہے) تو اسے بھلائی کی اتباع کرنی چاہیے اور آسانی کے ساتھ دیت ادا کرنی چاہیے۔ یعنی دیت طلب کرنے والا اچھے طریقے سے مطالبہ کرے اور دیت کی شرعی مقدار سے زیادہ کا طالب نہ ہو۔ اسی طرح دیت ادا کرنے والا بغیر پس و پیش اور تنگ کیے دیت ادا کر دے۔ یہ بھی کہا گیا ہے کہ آیت کریمہ میں (مِنْ أَخِيهِ) میں استعمال ہونے والا ’’مِنْ‘‘ بدلیت کا ہے تو اس صورت میں معنی ہوگا کہ مقتول بھائی کے عوض اور بدلے میں دیت ادا کرو، جیسا کہ اللہ عز وجل کے فرمان:","﴿ وَلَوْ نَشَاءُ لَجَعَلْنَا مِنْكُمْ مَلَائِكَةً فِي الْأَرْضِ ﴾ [الزخرف: ۶۰]","’’اگر ہم چاہتے تو تمہارے عوض فرشتے کر دیتے۔‘‘","تمہاری جگہ فرشتوں کو آباد کر دیتے۔ اس کے بعد مذکور ہے:","﴿ ذَلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ ﴾ [سورہ بقرہ: ۱۷۸]","’’تمہارے رب کی طرف سے یہ تخفیف اور رحمت ہے۔‘‘","یعنی پہلی امتوں کی نسبت آسانی اور نرمی ہے۔ تخفیف اور رحمت (یعنی، معافی یا دیت تین صورتوں) اللہ تعالیٰ کی طرف سے خاص تم پر ہوئی ہے ورنہ اس سے قبل اہل تورات کے لیے قصاص یا معافی تھی، دیت نہیں تھی اور اہل انجیل (عیسائیوں) میں صرف معافی ہی تھی، قصاص تھا نہ دیت۔ (ع، س)","﴿ فَمَنِ اعْتَدَى بَعْدَ ذَلِكَ فَلَهُ عَذَابٌ أَلِيمٌ ﴾ [سورہ بقرہ: ۱۷۸]","’’اس کے بعد جو سرکشی کرے تو اسے دردناک عذاب ہو گا۔‘‘","یعنی قبول دیت یا اخذ دیت کے بعد قتل بھی کر دے تو یہ سرکشی اور زیادتی ہے، (جس کی سزا اسے دنیا و آخرت میں بھگتنی ہوگی)۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ﴾.... قصاص میں تمہارے لیے زندگی ہے۔ (سورہ بقرہ: ۱۷۹) جب قاتل کو یہ خوف ہوگا کہ میں بھی قصاص میں قتل کر دیا جاؤں گا تو پھر اسے کسی کو قتل کرنے کی جرأت نہیں ہوگی اور اس خوف سے وہ قتل کرنے سے رک جائے گا اور اسی میں اس کی زندگی ہے۔ اور یہاں حیات سے مقصود قاتل کو قتل کر دینا ہے (اگرچہ بظاہر وہ قتل ہو رہا ہے مگر اس میں باقی معاشرے کے لیے زندگی ہے، جس معاشرے میں قانون قصاص نافذ ہو جاتا ہے وہاں یہ خوف معاشرے کو قتل و خونریزی سے محفوظ رکھتا ہے، اور معاشرے میں نہایت امن اور سکون رہتا ہے۔) امام ابوعبید نے کہا: یہاں حیات سے مراد منفعت ہے جیسا کہ عربی محاورہ ہے ’’لیس بفلان حیاة‘‘ یعنی فلاں کی زندگی بے فائدہ اور منفعت سے خالی ہے، اس سے خیر و شر میں سے کسی چیز کی توقع نہیں۔ اور سیدنا ابوشریح کعبی رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس کا کوئی آدمی قتل کیا گیا، ہو تو اس کے گھر والوں کو دو باتوں میں سے ایک کا اختیار ہے، وہ قتل کریں یا دیت وصول کر لیں۔‘‘ حدیث مبارکہ سے معلوم ہوا کہ قصاص یا دیت لینے کا اختیار مقتول کے ورثا کو ہے اور اس کے لیے قاتل کی رضامندی کا کچھ اعتبار نہیں، اس بارے میں پائے جانے والے فقہی اختلاف اور تفصیل کو ہم کتاب الحج میں سیدنا ابوشریح رضی اللہ عنہ کی حدیث کے ذیل میں بیان کر آئے ہیں۔"],"952":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَالْعَيْنَ بِالْعَيْنِ وَالْأَنْفَ بِالْأَنْفِ وَالْأُذُنَ بِالْأُذُنِ وَالسِّنَّ بِالسِّنِّ وَالْجُرُوحَ قِصَاصٌ ﴾","’’اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور خاص زخموں کا بدلہ ہے۔‘‘"],"956":["مقتول کے خون کے بدلے میں جو چیز مقتول کے وارثوں کو دی جائے، وہ دیت ہے اور دیت کی مقدار احادیث کی رو سے سو اونٹ یا اس کے مساوی قیمت سونے چاندی یا کرنسی کی شکل میں ہوگی۔ (ع، س) اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ﴾ ’’جو شخص کسی مسلمان کو بلا قصد مار ڈالے، اس پر ایک مسلمان غلام کی گردن آزاد کرنا اور مقتول کے عزیزوں کو خون بہا پہنچانا ہے۔‘‘ (سورہ نساء: ۹۲)"],"966":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا.... ﴾ [سورہ مائدہ: ۳۳]","’’بلا شبہ جو لوگ اللہ اور اس کے رسول سے جنگ کرتے ہیں ان کی سزا یہ ہے کہ انھیں قتل کر دیا جائے یا سولی پر چڑھا دیا جائے۔‘‘","﴿ أَوْ يُنْفَوْا مِنَ الْأَرْضِ.... ﴾ [سورہ مائدہ: ۳۳]","’’یا انھیں جلا وطن کر دیا جائے۔‘‘","(نَفَيْتُ فُلَانًا) کا معنی ہے: میں نے فلاں کو ملک بدر کر دیا اور علاقے سے بھگا دیا۔ نَفَيْتُ الدَّرَاهِمَ نَفَايَةَ کا معنی ہے: میں نے دراہم واپس کر دیے اور اگر نون کے اوپر پیش پڑھی جائے یعنی (النُّفَايَةَ) تو معنی ہوگا: قلیل مقدار میں کسی چیز کو عمومی حکم سے نکالنا۔ بہر حال اس مادہ میں نکالنے اور جلاوطن کرنے کا معنی پایا جاتا ہے۔"],"972":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَاللَّاتِي يَأْتِينَ الْفَاحِشَةَ مِنْ نِسَائِكُمْ فَاسْتَشْهِدُوا عَلَيْهِنَّ أَرْبَعَةً مِنْكُمْ فَإِنْ شَهِدُوا فَأَمْسِكُوهُنَّ فِي الْبُيُوتِ حَتَّى يَتَوَفَّاهُنَّ الْمَوْتُ أَوْ يَجْعَلَ اللَّهُ لَهُنَّ سَبِيلًا ﴾ [سورہ نساء: ۱۵]","’’تمھاری عورتوں میں سے جو بے حیائی کا کام کریں ان پر اپنے میں سے چار گواہ طلب کرو، اگر وہ گواہی دیں تو ان عورتوں کو گھروں میں قید رکھو، یہاں تک کہ موت ان کی عمریں پوری کر دے، یا اللہ تعالیٰ ان کے لیے کوئی اور راستہ نکال دے۔‘‘","سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مجھ سے لے لو، مجھ سے لے لو، اللہ تعالیٰ نے ان عورتوں کے لیے راہ نکال دی ہے۔ اگر شادی شدہ شادی شدہ کے ساتھ (ملوث ہو اور بدکاری) کرے تو سو کوڑے ہیں اور پتھر مارنا ہے اور کنوارا کنواری کے ساتھ کرے تو سو کوڑے ہیں اور ایک سال کے لیے شہر بدری ہے۔‘‘ حدیث مبارکہ میں اس حکم کی وضاحت ہے جس کا اللہ تعالیٰ کے فرمان:","﴿ أَوْ يَجْعَلَ اللَّهُ لَهُنَّ سَبِيلًا.... ﴾","’’یا اللہ ان کے لیے کوئی اور راستہ نکالے‘‘","میں وعدہ کیا گیا تھا۔ اللہ تعالیٰ نے ابتدائے اسلام میں بدکار عورت کی سزا یہ مقرر کی تھی کہ انھیں گھروں میں قید کر دیا جائے تا آنکہ اللہ تعالیٰ ان کے لیے کوئی راستہ نکال دے اب اس راستے کی وضاحت رسول کریم صلی اللہ علیہ وسلم کی زبان اقدس سے کر دی گئی۔"],"978":["اللہ سبحانہ وتعالیٰ نے قوم لوط کے عمل کے متعلق فرمایا:","﴿ أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ وَتَقْطَعُونَ السَّبِيلَ.... ﴾ [سورہ عنکبوت: ۲۹]","’’کیا تم مردوں کے پاس بدفعلی کے لیے آتے ہو اور راستے بند کرتے ہو۔‘‘","ایک معنی یہ بھی کیا گیا ہے کہ تم اولاد کے حصول کا راستہ چھوڑ دیتے ہو، دوسرے معنی ہیں: تم سراہ ہی بے حیائی کا ارتکاب کرتے ہو اور آنے جانے والوں سے چھیڑ خوانی کرتے ہو جس سے وہاں سے گزرتے ہوئے لوگ شرم محسوس کرتے ہیں اور راستے بند ہو جاتے ہیں۔"],"980":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا أَيْدِيَهُمَا.... ﴾ [سورہ مائدہ: ۳۸]","’’چوری کرنے والے مرد اور عورت کے ہاتھ کاٹ دیا کرو۔‘‘","چور اس شخص کو کہتے ہیں جو کسی کا مال اس کی حفاظت کی جگہ سے چھپ کر، پوشیدگی سے لے جائے۔ اگر وہ سامنے سے لے جائے تو وہ مُخْتَلِسٌ (اچکا، جو کسی کا مال جھپٹا مار کر لے جائے) یا مُنْتَهِبٌ (جو زبردستی غلبہ پا کر مال چھین لے) ہو گا۔"],"988":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿إِنَّ اللَّهَ اشْتَرَى مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوَالَهُمْ بِأَنَّ لَهُمُ الْجَنَّةَ﴾ ’’بلاشبہ اللہ تعالیٰ نے مسلمانوں سے ان کی جانوں کو اور ان کے مالوں کو اس بات کے عوض میں خرید لیا ہے کہ ان کو جنت ملے گی۔‘‘ (سورہ توبہ: ۱۱۱) اللہ عزوجل کا فرمان ہے:","﴿ هَلْ أَدُلُّكُمْ عَلَى تِجَارَةٍ تُنْجِيكُمْ مِنْ عَذَابٍ أَلِيمٍ ۝ تُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ وَتُجَاهِدُونَ فِي سَبِيلِ اللَّهِ.... ﴾ [الصف: ۱۰،۱۱]","’’کیا میں تمھیں وہ تجارت بتلا دوں جو تمھیں دردناک عذاب سے بچا لے؟ اللہ تعالیٰ پر اور اس کے رسول پر ایمان لاؤ اور اللہ کی راہ میں جہاد کرو۔‘‘","اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ ذَلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِي سَبِيلِ اللَّهِ وَلَا يَطَئُونَ مَوْطِئًا يَغِيظُ الْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَيْلًا.... ﴾ [التوبہ: ۱۲۰]","’’یہ اس سبب سے ہے کہ ان کو اللہ کی راہ میں جو پیاس لگی اور جو تھکان پہنچی اور جو بھوک لگی اور جو کسی ایسی جگہ چلے جو کفار کے لیے موجب غیظ ہوا ہو اور دشمنوں کی جو کچھ خبر لی۔‘‘","(وَلَا يَنَالُونَ) ’’اور جو دشمنوں کا نقصان کیا‘‘ کہا جاتا ہے: اس نے دشمن کا مال اسباب حاصل کر لیا یعنی اس کا سامان لوٹ لیا اور جانور چھین لیے۔ نِلْتُ اور اَنَالُ کے الفاظ کا معنی ہے: میں نے حاصل کیا اور میں مقصد کو پہنچا۔"],"989":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَأَنْفِقُوا فِي سَبِيلِ اللَّهِ﴾ ’’اللہ کے راستے میں خرچ کرو۔‘‘ (سورہ بقرہ: ۱۹۵) نیز ارشاد باری تعالیٰ ہے:","﴿ وَتُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِكُمْ ﴾ [الصف: ۱۱]","’’اور اللہ کی راہ میں اپنے مال سے جہاد کرو۔‘‘","ارشاد باری تعالیٰ ہے:","﴿ وَلَا يُنْفِقُونَ نَفَقَةً صَغِيرَةً ﴾ [التوبہ: ۱۲۱]","’’اور جو کچھ چھوٹا (بڑا) انھوں نے خرچ کیا۔‘‘","اور رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: «مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ دَعَاهُ خَزَنَةُ الْجَنَّةِ، كُلُّ خَزَنَةِ بَابٍ، أَيْ: فُلُ هَلُمَّ»...... ’’جس شخص نے اللہ کی راہ میں کسی چیز کا ایک جوڑا خرچ کیا تو اسے جنت کے داروغے بلائیں گے، جنت کے ہر دروازے کا داروغہ (اپنی طرف) بلائے گا کہ اے فلاں! اس دروازے سے آ۔‘‘ (صحیح بخاری: ۲۸۴۱، ۳۲۱۶، صحیح مسلم: ۱۰۲۷)"],"990":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ مِنْكُمْ مَنْ يُرِيدُ الدُّنْيَا وَمِنْكُمْ مَنْ يُرِيدُ الْآخِرَةَ ﴾ [آل عمران: ۱۵۲]","’’تم میں سے بعض دنیا چاہتے تھے اور بعض کا ارادہ آخرت کا تھا۔‘‘","نیز اللہ عزوجل کا فرمان ہے:","﴿ لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَاتَّبَعُوكَ ﴾ [التوبہ: ۴۲]","’’اگر جلد وصول ہونے والا مال و اسباب ہوتا اور ہلکا سا سفر ہوتا تو یہ ضرور آپ کے پیچھے ہو لیتے۔‘‘","’’عَرَضًا قَرِيبًا‘‘ سے مراد مال غنیمت ہے جس کا ملنا سہل الحصول ہو اور نبی اقدس صلی اللہ علیہ وسلم کا فرمان ہے: ’’اعمال کا دارومدار نیت پر ہے۔‘‘"],"991":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ قُلْ هَلْ تَرَبَّصُونَ بِنَا إِلَّا إِحْدَى الْحُسْنَيَيْنِ ﴾ [التوبہ: ۵۲]","’’کہہ دیجئے کہ تم ہمارے بارے میں جس چیز کا انتظار کر رہے ہو وہ دو بھلائیوں میں سے ایک ہے۔‘‘","یعنی کامیابی یا شہادت، حسنیین کا لفظ مؤنث آیا ہے کیونکہ اس سے مراد دو خصلتیں ہیں کہ ان دونوں میں سے جو چیز بھی ہمیں حاصل ہو، ہمارے لیے حسنہ (بھلائی) ہے۔ اللہ سبحانہ وتعالیٰ کا ارشاد ہے:","﴿ وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا ﴾ [آل عمران: ۱۶۹]","’’جو لوگ اللہ کی راہ میں شہید کیے گئے ہیں ان کو ہرگز مردہ نہ سمجھو۔‘‘","بعض کے نزدیک شہید کو شہید کہنے کی وجہ یہ ہے کہ وہ زندہ ہیں۔ ان کی روحیں جنت دارالسلام میں رکھ کر لوٹا دی جاتی ہیں جبکہ باقی لوگوں کے ساتھ یہ معاملہ نہیں ہوتا ان کی روحیں قیامت والے دن ہی لوٹائی جائیں گی۔ بعض کے نزدیک اس کی وجہ یہ ہے کہ جب ان کی روحیں جنت میں جاتی ہیں تو وہاں اللہ تعالیٰ اور فرشتوں کو موجود پاتی ہیں۔ بعض کے نزدیک اس کی وجہ یہ ہے کہ راہ جہاد میں مرنے والوں کی روحیں گزشتہ امتوں کے انبیاء کرام کے تبلیغ کرنے اور رسالت کا حق ادا کرنے کی گواہی دیں گی جب ان کی تبلیغ سے ان کی امتیں انکار کریں گی اللہ تعالیٰ کا فرمان ہے:","﴿ لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ ﴾ [سورہ بقرہ: ۱۴۳]","’’تاکہ تم لوگوں پر گواہ ہو جاؤ۔‘‘","(یاد رہے! لفظ شہید کے لغوی معنی گواہی دینے اور موجود ہونے کے ہیں۔ ع،س)"],"993":["اللہ تعالیٰ کا فرمان ہے:","﴿ وَمَنْ يَخْرُجُ مِنْ بَيْتِهِ مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ ثُمَّ يُدْرِكْهُ الْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ ﴾ [سورہ نساء: ۱۰۰]","’’اور جو کوئی اپنے گھر سے اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کی طرف نکل کھڑا ہوا، پھر اسے موت نے آ پکڑا تو یقیناً اس کا اجر اللہ تعالیٰ کے ذمہ ثابت ہو گیا۔‘‘","سیدنا عمر رضی اللہ عنہ نے کہا: اے اللہ! مجھے اپنے رسول کے شہر میں شہادت کے خلعت سے سرفراز فرما۔ (صحیح بخاری: ۱۸۹۰)"],"994":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ اِنْفِرُوا خِفَافًا وَثِقَالًا ﴾ [التوبہ: ۴۱]","’’نکل کھڑے ہو جاؤ ہلکے پھلکے ہو تو بھی اور بھاری بھر کم ہو تو بھی۔‘‘","اس کے مختلف مفہوم بیان کیے گئے ہیں، مثلاً کشادہ دست ہو یا تنگ دست، نقل و حرکت تمہارے لیے آسان ہو یا دوبھر، جناب قتادہ نے کہا: اس سے مراد خوشی سے یا نا خوشی سے نکلنے کے ہیں، اللہ تعالیٰ کا فرمان ہے:","﴿ إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا ﴾ [التوبہ: ۳۹]","’’اگر تم نے کوچ نہ کیا تو تمہیں اللہ تعالیٰ دردناک سزا دے گا۔‘‘","نیز اللہ تعالیٰ کا ارشاد ہے:","﴿ فَانْفِرُوا ثُبَاتٍ ﴾ [سورہ نساء: ۷۱]","’’پھر گروہ گروہ بن کر کوچ کرو۔‘‘","سیدنا ابن عباس رضی اللہ عنہ نے کہا: اس سے مراد ہے کہ جدا جدا اٹکڑیاں (دستے) بنا کر جہاد کے لیے نکلو، کہا جاتا ہے کہ ثبات (جمع) کا مفرد ’’ثُبَةٌ‘‘ ہے۔"],"995":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ ﴾ [سورہ نساء: ۹۵]","’’اپنی جانوں اور مالوں سے اللہ کی راہ میں جہاد کرنے والے مومن اور بغیر عذر کے بیٹھے رہنے والے مومن برابر نہیں۔‘‘","اللہ جل شانہ کا فرمان ہے:","﴿ لَيْسَ عَلَى الْأَعْمَى حَرَجٌ ﴾ [النور: ۶۱]","’’اندھے پر مطلقاً کوئی حرج نہیں۔‘‘","نیز اللہ عزوجل کا فرمان ہے:","﴿ لَيْسَ عَلَى الضُّعَفَاءِ وَلَا عَلَى الْمَرْضَى وَلَا عَلَى الَّذِينَ لَا يَجِدُونَ مَا يُنْفِقُونَ حَرَجٌ إِذَا نَصَحُوا لِلَّهِ وَرَسُولِهِ ﴾ [التوبہ: ۹۱]","’’ضعیفوں اور بیماروں پر اور ان پر جن کے پاس خرچ کرنے کو کچھ بھی نہیں کوئی حرج نہیں بشرطیکہ وہ اللہ اور اس کے رسول کی خیر خواہی کرتے رہیں۔‘‘"],"997":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ ﴾ [الانفال: ۶۰]","’’تم ان کے مقابلے کے لیے اپنی طاقت بھر قوت کی تیاری کرو۔‘‘","سیدنا عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’خبردار! بلاشبہ قوت تیر اندازی ہے۔‘‘ آپ صلی اللہ علیہ وسلم نے تین بار یہ ارشاد کو دوہرایا۔ (صحیح مسلم: ۱۹۱۷) اللہ عزوجل کے فرمان","﴿ صَابِرُوا وَرَابِطُوا ﴾ [آل عمران: ۲۰۰]","’’ایک دوسرے کو تھامے رکھو اور جہاد کے لیے تیار ہو۔‘‘","کے متعلق کہا گیا کہ اس سے مراد میدان جنگ یا محاذ جنگ میں مورچہ بند ہو کر ہمہ وقت چوکنا اور تیار رہنا ہے، نیز ان کے مقابلے کے لیے گھوڑے پالنا ہے۔"],"998":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَمِنْ رِبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ ﴾ [الانفال: ۶۰]","’’اور گھوڑوں کو تیار رکھنے سے قوت تیار رکھو کہ اس سے تم اللہ کے دشمنوں کو خوف زدہ رکھ سکو۔‘‘","اس سے مقصود اپنے آنگن میں گھوڑا باندھنا اور اسے جہاد کی غرض سے پالنا پوسنا ہے۔"],"1004":["سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب فتح مکہ والے سال مکہ مکرمہ میں داخل ہوئے تو آپ کے سر مبارک پر خود تھا۔ (صحیح بخاری: ۴۲۸۶، صحیح مسلم: ۱۳۵۷)"],"1023":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَكَأَيِّنْ مِنْ نَبِيٍّ قَاتَلَ مَعَهُ رِبِّيُّونَ كَثِيرٌ ﴾ [آل عمران: ۱۴۶]","’’بہت سے نبیوں کے ہم رکاب ہو کر، بہت سی جماعتیں اور گروہ جہاد کر چکے ہیں۔‘‘","(الرِّبِّيُّونَ) سے مراد بہت سے گروہ اور جتھے ہیں اس کا واحد الربی ہے اور (الرَّبَّةُ) کا معنی ایک جماعت کے ہیں۔ اللہ جل و شانہ کا فرمان ہے:","﴿ وَمَا ضَعُفُوا وَمَا اسْتَكَانُوا وَاللَّهُ يُحِبُّ الصَّابِرِينَ ﴾ [آل عمران: ۱۴۶]","’’نہ تو انھوں نے ہمت ہاری نہ سست رہے، اور اللہ صبر کرنے والوں کو (ہی) چاہتا ہے۔‘‘","نیز اللہ عزوجل کا ارشاد ہے:","﴿ وَمَا كَانَ قَوْلَهُمْ إِلَّا أَنْ قَالُوا رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا ﴾ [آل عمران: ۱۴۷]","’’وہ یہی کہتے رہے کہ اے پروردگار! ہمارے گناہوں کو بخش دے۔‘‘","اللہ عزوجل کا فرمان ہے:","﴿ وَلَمَّا بَرَزُوا لِجَالُوتَ وَجُنُودِهِ قَالُوا رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا ﴾ [سورہ بقرہ: ۲۵۰]","’’جب ان کا جالوت اور اس کے لشکر سے مقابلہ ہوا تو انھوں نے دعا مانگی کہ اے پروردگار! ہمیں صبر دے۔‘‘","یعنی ہمارے دلوں میں یوں صبر ڈال دے جیسے برتن سے پانی انڈیلا جاتا ہے۔ مطلب ہے کہ ہمیں صبر و ثبات کی دولت سے مالا مال کر دے اور ہمارے قلوب کو قرار اور طمانیت سے لبالب بھر دے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا ﴾ [آل عمران: ۲۰۰]","’’اے ایمان والو! تم ثابت قدم رہو اور ایک دوسرے کو تھماے رکھو۔‘‘","بعض علماء نے (اصْبِرُوا) کا معنی کیا ہے: اپنے دین پر ڈٹ جاؤ اور طاعات کے اختیار کرنے میں مضبوط اور ثابت قدم رہو اور (وَصَابِرُوا) کا معنی کیا ہے: جنگ اور جہاد کی شدتوں میں دشمن کے مقابلے میں ڈٹے رہنا۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ ﴾ [الانفال: ۶۵]","’’اگر تم میں بیس بھی صبر کرنے والے ہوں گے تو دوسو پر غالب رہیں گے۔‘‘","سیدنا جابر رضی اللہ عنہ نے کہا: ہم نے رسول اللہ صلی اللہ علیہ وسلم کی بیعت کی تھی کہ (میدان جنگ سے) بھاگیں گے نہیں۔ (صحیح مسلم: ۱۸۵۶)"],"1029":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَلَا تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَمَ لَسْتَ مُؤْمِنًا ﴾ [سورہ نساء: ۹۴]","’’اور جو تم سے سلام علیک کرے تم اسے یہ نہ کہہ دو کہ تو ایمان والا نہیں۔‘‘","سیدنا ابن عباس رضی اللہ عنہما نے کہا: ایک شخص اپنی بکریاں چرا رہا تھا، مسلمان اس کے پاس سے گزرے تو چرواہے نے السلام علیکم کہا (بعض صحابہ نے سمجھا کہ شاید وہ جان بچانے کے لیے اپنے کو مسلمان ظاہر کر رہا ہے) چنانچہ انھوں نے اسے قتل کر ڈالا اور اس کی بکریاں لے لیں اور انھیں بطور مال غنیمت لے کر حضور صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو گئے، جس پر اللہ تعالیٰ نے یہ آیت نازل فرمائی (عَرَضَ الْحَيَاةِ الدُّنْيَا) تک، دنیاوی زندگی کے اسباب سے مراد مال غنیمت ہے، سیدنا ابن عباس رضی اللہ عنہما نے آیت کریمہ کے لفظ (السَّلَمَ) کو (السَّلَام) پڑھا ہے۔ (صحیح بخاری: ۴۵۹۱، صحیح مسلم: ۳۰۲۵)"],"1030":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ إِنَّ اللَّهَ يُحِبُّ الَّذِينَ يُقَاتِلُونَ فِي سَبِيلِهِ صَفًّا كَأَنَّهُمْ بُنْيَانٌ مَرْصُوصٌ ﴾ [الصف: ۴]","’’بے شک اللہ تعالیٰ ان لوگوں سے محبت کرتا ہے جو اس کی راہ میں صف بستہ جہاد کرتے ہیں گویا وہ سیسہ پلائی ہوئی عمارت ہیں۔‘‘","اللہ عزوجل کا فرمان ہے:","﴿ وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ الْمُؤْمِنِينَ مَقَاعِدَ لِلْقِتَالِ ﴾ [آل عمران: ۱۲۱]","’’اے نبی! اس وقت کو بھی یاد کرو جب صبح ہی صبح آپ اپنے گھر سے نکل کر مسلمانوں کو میدان جنگ میں لڑائی کے مورچوں پر باقاعدہ بٹھا رہے تھے۔‘‘"],"1032":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ إِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا زَحْفًا ﴾ [الانفال: ۱۵]","’’جب تم کافروں سے رو برو مقابل ہو جاؤ۔‘‘","یعنی زاحفین۔ دونوں فریقوں کا ایک دوسرے کے مقابل اور روبرو ہو کر آہستہ آہستہ پیش قدمی کرنا۔ نیز ارشاد ربانی ہے:","﴿ وَمَنْ يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُ إِلَّا مُتَحَرِّفًا لِقِتَالٍ ﴾ [الانفال: ۱۶]","’’اور جو شخص ان سے اس موقع پر پشت پھیرے گا مگر ہاں جو لڑائی کے لیے پینترا بدلتا ہو۔‘‘","اللہ جل ذکرہ کا فرمان ہے:","﴿ إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ ﴾ [الانفال: ۶۵]","’’اگر تم میں بھی صبر کرنے والے ہوں گے تو دوسو پر غالب رہیں۔‘‘","﴿ أَوْ مُتَحَيِّزًا إِلَى فِئَةٍ ﴾ [الانفال: ۱۶]","’’یا جو (اپنی) جماعت کی طرف پناہ لینے آتا۔‘‘","تَحَيُّز کے معنی ملنے اور پناہ لینے کے ہیں۔ کوئی مجاہد لڑتا لڑتا تنہا رہ جائے تو بہ لطائف الحیل میدان جنگ سے ایک طرف ہو جائے تاکہ وہ اپنی جماعت کی طرف پناہ حاصل کرے اور اس کی مدد سے دوبارہ حملہ کرے، کہا گیا ہے: تَحَيُّز، تَحَوُّذ اور اِنْحَاذ تینوں الفاظ کا معنی ایک ہی ہے۔ الْحَيِّز دراصل کنارے اور گوشے کو کہتے ہیں، عربی محاورہ ہے: فلان مانع لحوزتہ یعنی فلاں صاحب اپنی گرہ میں موجود چیز کو صرف کرنے سے گریزاں ہیں۔ الْفِئَةُ سے مراد فرقہ اور جماعت ہے، اس کی جمع فِئَات یا فِئُونَ آتی ہے۔"],"1034":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَخُذُوهُمْ وَاحْصُرُوهُمْ﴾ ’’انہیں گرفتار کرو، ان کا محاصرہ کرلو۔‘‘ (التوبہ: ۵) (فَخُذُوهُمْ) کا معنی ہے انہیں قیدی بنالو، عربی زبان میں قیدی کو الاخيذ کہا جاتا ہے تو پھر وَاحْصُرُوهُمْ کا معنی ہوا انہیں محبوس کرلو (وَالْحَصِيرُ) سے مراد جیل ہے جہاں مجرموں کو بند رکھا جاتا ہے۔ اللہ تعالیٰ کا فرمان ہے:","﴿ وَجَعَلْنَا جَهَنَّمَ لِلْكَافِرِينَ حَصِيرًا ﴾ [الاسراء: ۸]","’’اور ہم نے منکروں کا قید خانہ جہنم کو بنا رکھا ہے۔‘‘","اللہ عزوجل کا فرمان ہے:","﴿ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ ﴾ [التوبہ: ۵]","’’اور ان کی تاک میں ہر گھاٹی میں جا بیٹھو۔‘‘","یعنی ان کے ہر راستے پر گھات لگا کر بیٹھو۔ مطلب یہ ہے کہ ہر وقت تم ان کی ٹوہ میں رہو، ہر راستے سے ان کا تعاقب کرو حتیٰ کہ تمہاری اجازت کے بغیر ان کے لیے نقل وحرکت ممکن نہ رہے۔ اللہ تبارک و تعالیٰ کا فرمان ہے:","﴿ إِنَّ رَبَّكَ لَبِالْمِرْصَادِ ﴾ [الفجر: ۱۴]","’’یقیناً تیرا رب گھات میں ہے۔‘‘","یعنی جس شاہرائے حیات سے تو نے گزر کر اللہ کے حضور پہنچنا ہے وہ راستہ اللہ کے پاس سے ہو کر گزرتا ہے یا اس جملے کا مطلب ہے: اللہ تمام مخلوقات کے اعمال دیکھ رہا ہے اور اس کے مطابق وہ دنیا اور آخرت میں جزا دیتا ہے۔ اور جل ذکرہ کا فرمان ہے:","﴿ حَتَّى إِذَا أَثْخَنْتُمُوهُمْ فَشُدُّوا الْوَثَاقَ ﴾ [محمد: ۴]","’’جب ان کو اچھی طرح کچل ڈالو تو اب خوب مضبوط قید وبند سے گرفتار کرو۔‘‘","بعض نے کہا: الْإِثْخَانُ سے مراد زور دار لڑائی اور معرکہ آرائی ہے۔ بعض نے کہا: اس سے مراد زیادہ سے زیادہ ان کے افراد کو قتل کرنا ہے اور ان پر غلبہ اور تسلط پانا ہے، بعض علماء نے (حَتَّى يُثْخِنَ فِي الْأَرْضِ) کا معنی کیا ہے کہ آپ زیادہ سے زیادہ دشمن کو قتل کریں اور ان کا عددی نقصان کریں اور بعض کے نزدیک ان الفاظ کا معنی ہے: تا آنکہ آپ کو زمین میں پوری طرح غلبہ، تسلط اور اقتدار مل جائے۔"],"1035":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا ﴾ [محمد: ۴]","’’پھر اختیار ہے خواہ احسان کر کے چھوڑ دو یا فدیہ (عوض اور بدل) لے کر، یہاں تک کہ لڑائی اپنے ہتھیار رکھ دے۔‘‘","وزر ہر اس چیز کو کہا جاتا ہے جو انسان اٹھائے ہوئے ہو، اسلحہ اور آلات حرب وضرب کو بھی عربی زبان میں اوزار کہہ دیا جاتا ہے کیونکہ ایک مجاہد انہیں ہر وقت اٹھائے رکھتا ہے، اس معنی میں یہ لفظ قرآن مجید میں آیا ہے","﴿ يَحْمِلُونَ أَوْزَارَهُمْ ﴾","’’وہ اپنے بوجھ اپنی پیٹھوں پر لادے ہوں گے‘‘","یعنی اپنی پشتوں پر گناہوں کا بار اٹھائے ہوئے ہوں گے۔ جناب سعید بن جبیر رحمہ اللہ اللہ عزوجل کے فرمان ﴿حَتَّى إِذَا أَثْخَنْتُمُوهُمْ فَشُدُّوا الْوَثَاقَ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً﴾.... کے متعلق کہا کہ کافروں کے قیدیوں کے عوض فدیہ نہ لیا جائے اور نہ احسان کر کے انہیں چھوڑا ہی جائے بلکہ ہر حالت میں انہیں قتل ہی کیا جائے، اور انہوں نے اللہ سبحانہ وتعالیٰ کے فرمان","﴿ حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا ﴾ [محمد: ۴]","’’تا وقتیکہ لڑائی اپنے ہتھیار رکھ دے۔‘‘","کا تعلق سیدنا عیسیٰ علیہ السلام کے آنے کے ساتھ جوڑا ہے کہ یہ کیفیت ان کے نزول کے بعد پیش آئے گی۔"],"1039":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ يَسْأَلُونَكَ عَنِ الْأَنْفَالِ قُلِ الْأَنْفَالُ لِلَّهِ وَالرَّسُولِ ﴾ [الانفال: ۱]","’’یہ لوگ آپ سے غنیمتوں کا حکم دریافت کرتے ہیں، آپ فرما دیجیے! کہ یہ غنیمتیں اللہ کی ہیں اور رسول کی ہیں۔‘‘","انفال سے مراد غنیمتیں ہیں اس کا واحد نفل ہے جس کے معنی زیادہ کے ہیں۔ ہر وہ چیز جو مطلوبہ مقدار سے زائد ہو اسے نفل کہہ دیا جاتا ہے، مال غنیمت (وہ مال و اسباب جو کافروں کے ساتھ جنگ میں مسلمانوں کے ہاتھ لگے) کو نفل (زیادہ) اس لیے کہا جاتا ہے کہ یہ ان چیزوں میں سے ایک ہے جو پچھلی امتوں پر حرام تھیں۔ یہ گویا امت محمدیہ پر ایک زائد چیز حلال کی گئی ہے، اسی بنا پر فرض نمازوں سے آگے پیچھے پڑھی جانے والی زائد رکعات کو نوافل کہا جاتا ہے کیونکہ وہ فرائض سے اضافی ایک چیز ہوتی ہے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَكُلُوا مِمَّا غَنِمْتُمْ حَلَالًا طَيِّبًا ﴾ [الانفال: ۶۹]","’’پس جو کچھ حلال اور پاکیزہ غنیمت تم نے حاصل کی ہے، خوب کھاؤ پیو۔‘‘","اور نبی مکرم صلی اللہ علیہ وسلم کا ارشاد گرامی ہے: ’’میرے لیے غنیمتیں حلال کی گئی ہیں اور مجھ سے پہلے کسی کے لیے حلال نہ تھیں۔‘‘ (صحیح بخاری: ۳۳۵، صحیح مسلم: ۵۲۱)"],"1043":["جو مال مقتول کے پاس ہو، اس کا قاتل ہی اس کا حقدار سمجھا جاتا ہے اور اسے اصطلاحاً ’’سلب‘‘ کہتے ہیں۔"],"1045":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَمَا كَانَ لِنَبِيٍّ أَنْ يَغُلَّ وَمَنْ يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ الْقِيَامَةِ﴾ ’’ناممکن ہے کہ نبی سے خیانت ہو جائے، ہر خیانت کرنے والا خیانت کو لیے ہوئے قیامت کے دن حاضر ہوگا۔‘‘ (آل عمران: ۱۶۱) (يَغُلُّ) کا معنی ہے: وہ خیانت کرتا ہے۔ جب کوئی شخص مال غنیمت میں سے کوئی چیز چرا لے تو کہا جاتا ہے: غل فی الغنم۔ بعض نے اس لفظ کو (يُغَلُّ) یا کے اوپر پیش اور غین کے اوپر زبر کے ساتھ پڑھا ہے۔ تب معنی ہوگا: کسی نبی کی خیانت نہیں کی جا سکتی آپ صلی اللہ علیہ وسلم نے اپنے صحابہ کو خیانت وغیرہ سے باز رہنے کی تلقین فرمائی اور اس کی سخت مذمت فرمائی ہے۔ بعض نے کہا: اس لفظ کا معنی ہے کہ کسی پیغمبر کی طرف خیانت کو منسوب نہیں کیا جا سکتا کہ پیغمبر سے کسی قسم کی خیانت کا صدور ممکن ہی نہیں کیونکہ خیانت نبوت کے منافی ہے۔ خیانت کو غلول کہنے کی وجہ یہ ہے کہ ہاتھوں کو اس سے رکے رہنے کی تلقین ہے اور لفظ غلت کے معنی روکنے اور بند کرنے کے ہیں۔"],"1048":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَاعْلَمُوا أَنَّمَا غَنِمْتُمْ مِنْ شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ ﴾ [الانفال: ۴۱]","’’جان لو کہ تم جس قسم کی جو کچھ غنیمت حاصل کرو اس میں سے پانچواں حصہ تو اللہ کا ہے۔‘‘","اور نبی مکرم صلی اللہ علیہ وسلم نے قبیلہ عبدالقیس کے وفد سے فرمایا تھا: ’’جو تمہیں غنیمت حاصل ہو اس میں سے خمس نکالنا۔‘‘ (صحیح بخاری: ۴۳۶۹، صحیح مسلم: ۱۷)"],"1049":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ ﴾ [الحشر: ۶]","’’اور ان کا جو مال اللہ تعالیٰ نے اپنے رسول کے ہاتھ لگایا ہے جس پر نہ تم نے اپنے گھوڑے دوڑائے ہیں اور نہ اونٹ۔‘‘","کہا جاتا ہے: وَجِيفًا یعنی سواری کے چلنے کی تیزی اور سرعت عربی کے جملے أَوْجَفَهَا رَاكِبُهَا إِيجَافًا کا معنی ہے سوار نے اپنی سواری کو سرپٹ دوڑا دیا۔ اللہ تعالیٰ کا فرمان ہے:","﴿ قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ ﴾ [النازعات: ۸]","’’(بہت سے) دل اس دن دھڑکتے ہوں گے۔‘‘","یعنی قیامت کے اہوال اور شدائد سے دھک دھک کرتے ہوں گے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ مَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْ أَهْلِ الْقُرَى ﴾ [الحشر: ۷]","’’بستیوں والوں کا جو (مال) اللہ تعالیٰ تمہارے لڑے بھڑے بغیر اپنے رسول کے ہاتھ لگائے۔‘‘","نیز اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ كَيْ لَا يَكُونَ دُولَةً بَيْنَ الْأَغْنِيَاءِ مِنْكُمْ ﴾ [الحشر: ۷]","’’تاکہ تمہارے دولت مندوں کے ہاتھ میں ہی یہ مال گردش کرتا نہ رہ جائے۔‘‘","(الدَّوْلَةُ) سے مراد ہر وہ چیز ہے جو مال کے عوض حاصل کی جا سکے نیز (الدُّوْلَةُ) سے مراد تنگی اور بدحالی کی حالت سے نکل کر آسودگی، خوشحالی اور ایسی حالت میں پہنچ جانا ہے جو قابل رشک اور باعث صدر افتخار ہو۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَتِلْكَ الْأَيَّامُ نُدَاوِلُهَا بَيْنَ النَّاسِ ﴾ [آل عمران: ۱۴۰]","’’ہم ان دنوں کو لوگوں کے درمیان ادلتے بدلتے رہتے ہیں۔‘‘","’’أَدَالَ اللَّهُ فُلَانًا مِنْ فُلَانٍ‘‘ کا معنی ہے: اللہ کریم نے فلاں کو فلاں پر غلبہ عطا فرمایا ہے۔ غالب اور کامیاب شخص کو الْمُدَالُ کہا جاتا ہے۔ لفظ الدُّوْلَةُ کی جمع دُوَل اور دُوْلَات آتی ہے۔"],"1052":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَإِنْ جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا ﴾ [الانفال: ۶۱]","’’اگر وہ صلح کی طرف جھکیں تو تو بھی صلح کی طرف جھک جا۔‘‘"],"1053":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ قَاتِلُوا الَّذِينَ لَا يُؤْمِنُونَ بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ وَلَا يَدِينُونَ دِينَ الْحَقِّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ حَتَّى يُعْطُوا الْجِزْيَةَ عَنْ يَدٍ وَهُمْ صَاغِرُونَ ﴾ [التوبہ: ۲۹]","’’ان لوگوں سے لڑو جو اللہ پر اور قیامت کے دن پر ایمان نہیں لاتے جو اللہ اور اس کے رسول کی حرام کردہ شے کو حرام نہیں جانتے، نہ دین حق کو قبول کرتے ہیں ان لوگوں میں سے جنہیں کتاب دی گئی ہے، یہاں تک کہ وہ ذلیل و خوار ہو کر اپنے ہاتھ سے جزیہ ادا کریں۔‘‘","اللہ تعالیٰ کے ارشاد (عَنْ يَدٍ) کا مطلب ہے: ذلیل و خوار ہو کر اور اس اعتراف سے جزیہ دیں کہ دین اسلام ہی تمام ادیان پر غالب اور بلند ہے، اس لفظ کا ایک مفہوم یہ بھی بیان کیا گیا ہے کہ کفار سے جزیہ لے کر انہیں زندگی کی ضمانت دینا کافروں پر مسلمانوں کی طرف سے ایک انعام اور احسان ہے۔ ’’ید‘‘ کا لفظ عربی زبان میں احسان کے لیے مستعمل ہے، بعض نے (عَنْ يَدٍ) کا مطلب یہ بیان کیا ہے کہ جزیہ کی رقم کی نقد ادائیگی ہوا دھار نہیں۔","﴿ وَهُمْ صَاغِرُونَ ﴾","’’اور وہ ذلیل و خوار ہوں‘‘","صغار کا معنی ہے ذلت و نکبت یعنی جزیہ وصول کرنے والا مسلمان افسر کرسی پر تمکنت اور وقار کے ساتھ براجمان ہو اور جزیہ کی ادائیگی کرنے والے قطار میں کھڑے ہو کر جزیہ ادا کریں کہ جس سے ان پر اسلام کا حکم نافذ ہو اور اسلام کا حکم اہل شرک کے حکم پر غلبہ رکھتا ہو، اللہ تعالیٰ کا ارشاد ہے:","﴿ وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ ﴾ [سورہ بقرہ: ۶۱]","’’اور ان پر ذلت اور مسکنت ڈال دی گئی ہے۔‘‘","بعض کے نزدیک ذلت سے مراد جزیہ کی ادائیگی ہے اور مسکنت سے مراد دل کا افلاس ہے۔ آدمی خواہ کتنا ہی مالدار ہو مگر اس کا دل مفلسی کا شکار ہو یہی کیفیت یہود کی ہے۔"],"1060":["اللہ سبحان و تعالیٰ کا فرمان ہے:","﴿ وَإِذَا حَلَلْتُمْ فَاصْطَادُوا ﴾ [سورہ مائدہ: ۲]","’’جب احرام اتار ڈالو تو شکار کھیل سکتے ہو۔‘‘","’’صید‘‘ شکار کو کہتے ہیں اور اس سے مراد حلال جنگلی جانوروں کا شکار ہے جو بالعموم کسی کے قبضہ میں نہیں ہوتے۔ اللہ تعالیٰ کا فرمان ہے: ﴿وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ اللَّهُ فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ﴾ .... اور جن شکار کھیلنے والے جانوروں کو تم نے سدھا رکھا ہے یعنی جنہیں تم تھوڑا بہت وہ سکھاتے ہو جس کی تعلیم اللہ تعالیٰ نے تمھیں دے رکھی ہے پس جس شکار کو وہ تمھارے لیے پکڑ کر روک رکھیں تو تم اس سے کھاؤ۔‘‘ (سورہ مائدہ: ۴) (مِنَ الْجَوَارِحِ) شکار کھیلنے والے جانوروں سے، جارحۃ کی جمع ہے۔ اَلصَّوَائِدِ شکاری جانور کے معنی میں ہے، نیز یہ لفظ ’’کاسب‘‘ (کمانے والا) کے معنی میں ہے۔ اللہ تعالیٰ کا فرمان ہے: ﴿وَيَعْلَمُ مَا جَرَحْتُمْ﴾ .... اور جو کچھ تم دل میں کرتے ہو۔ یعنی کماتے ہو (الانعام: ۶۰) (مُكَلِّبِينَ) شکار کے اوپر کتا چھوڑنے والے شخص کو ’’مُكَلِّب‘‘ کہتے ہیں اور اس کو بھی جو کتے کو سکھلاتا اور تربیت دیتا ہے۔ اسی طرح لفظ ’’كَلَّاب‘‘ کتے کے مالک اور شکار کنندہ ہر دو اشخاص پر بولا جاتا ہے۔"],"1061":["اللہ سبحانہ و تعالیٰ کا فرمان ہے: ﴿وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ﴾ .... اور اہل کتاب کا ذبیحہ تمہارے لیے حلال ہے اور تمہارا ان کے لیے حلال ہے۔‘‘ (سورہ مائدہ: ۵)"],"1074":["اللہ تعالیٰ کا فرمان ہے: ﴿أُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وَطَعَامُهُ مَتَاعًا لَكُمْ وَلِلسَّيَّارَةِ....﴾ ’’تمہارے لیے دریا کا شکار پکڑنا اور اس کا کھانا حلال کیا گیا ہے۔ تمہارے فائدے کے واسطے اور مسافروں کے واسطے۔‘‘ (سورہ مائدہ: ۹۶)"],"1083":["اللہ سبحانہ و تعالیٰ کا فرمان ہے:","﴿ وَآخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴾ [یونس: ۱۰]","’’اور ان کی اخیر بات یہ ہوگی تمام تعریفیں اللہ کے لیے ہیں جو سارے جہان کا مالک ہے۔‘‘","سیدنا ابن عباس رضی اللہ عنہما سے اللہ عزوجل کے فرمان","﴿ دَعْوَاهُمْ فِيهَا سُبْحَانَكَ اللَّهُمَّ ﴾ [یونس: ۱۰]","ان کے منہ سے یہ بات نکلے گی ’’سُبْحَانَكَ اللَّهُمَّ‘‘","کے متعلق مروی ہے کہ جب اہل جنت کو کسی چیز کی طلب ہوگی تو وہ کہیں گے سُبْحَانَكَ اللَّهُمَّ تو ان کا مطلوب حسب منشاء ان کے پاس آ جائے گا، جب وہ اللہ تعالیٰ کی عطا کردہ نعمتیں نوش کر لیں گے تو کہیں گے: اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ تو یہ کلمہ ان کی اخیر بات ہوگی۔"],"1091":["اللہ سبحانہ و تعالیٰ کا فرمان ہے:","﴿ فَمَا لَبِثَ أَنْ جَاءَ بِعِجْلٍ حَنِيذٍ ﴾ [ھود: ۶۹]","’’اور (ابراہیم علیہ السلام) بغیر کسی تاخیر کے گائے کا بھنا ہوا بچھڑا لے آئے۔‘‘","(اَلْحَنِيذُ) اس گوشت کو کہتے ہیں جسے گرم پتھروں پر بھونا گیا ہو۔"],"1093":["نبی کریم صلی اللہ علیہ وسلم کا فرمان ہے: «فَضْلُ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ الثَّرِيدِ عَلَى الطَّعَامِ»...... ’’سیدہ عائشہ رضی اللہ عنہا کی فضیلت تمام خواتین پر ایسی ہے جیسے تمام کھانوں پر ثرید کی فضیلت ہے۔‘‘ (صحیح بخاری: ۳۷۷۰، صحیح مسلم: ۲۴۳۱) سیدنا عقبہ بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے آپ صلی اللہ علیہ وسلم کو خزیرہ (حریرہ کی ایک قسم) کیلئے جو ہم نے تیار کیا تھا روک لیا۔ (صحیح بخاری: ۵۴۰۱)"],"1095":["سَلْق: ایک قسم کی سبزی جس کے پتے لمبے اور جڑ گہری ہوتی ہے، پکا کر کھائی جاتی ہے۔ (ع، س)"],"1098":["اللہ سبحانہ و تعالیٰ کا فرمان ہے:","﴿ وَشَجَرَةً تَخْرُجُ مِنْ طُورِ سَيْنَاءَ تَنْبُتُ بِالدُّهْنِ ﴾ [المومنون: ۲۰]","’’اور وہ درخت جو طور سینا پہاڑ سے نکلتا ہے جو تیل نکالتا ہے اور کھانے والے کے لیے سالن ہے۔‘‘","یعنی زیتون کے پھل میں روغن ہوتا ہے، امام زہری نے کہا: یہ درخت اگتا ہے اور اس میں روغن موجود ہوتا ہے، یہ ترکیب عربی کی اس ترکیب کی طرح ہے جَاءَ زَيْدٌ بِالسَّيْفِ زید تلوار سمیت آیا۔ اللہ عزوجل کا فرمان ہے:","﴿ وَصِبْغٍ لِلْآكِلِينَ ﴾ [المومنون: ۲۰]","’’اور کھانے والوں کے لیے سالن ہے۔‘‘","یعنی زیتون کے تیل سے روٹی کھانے والا رنگتا ہے عربی میں سالن کو صبغ (رنگ) کہا جاتا ہے کیوں کہ روٹی، سالن میں ڈبو کر گویا رنگی جاتی ہے۔"],"1111":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ هَلْ أَتَاكَ حَدِيثُ ضَيْفِ إِبْرَاهِيمَ الْمُكْرَمِينَ ﴾ [الذاریات: ۲۴]","’’کیا تجھے ابراہیم علیہ السلام کے معزز مہمانوں کی خبر بھی پہنچی ہے؟‘‘","بعض کے نزدیک ان کے معزز ہونے کا مفہوم یہ ہے کہ سیدنا ابراہیم علیہ السلام نے انھیں بہت جلد مہمانی سے مشرف فرمایا: ان کی خاطر تواضع بنفس نفیس فرمائی، ان سے خندہ پیشانی اور کشادہ روئی سے پیش آئے جبکہ بعض کے نزدیک مہمانوں کا تعزز اس پہلو سے تھا کہ وہ اللہ تعالیٰ کے ہاں بلند مقام و مرتبہ کے حامل تھے کیونکہ فرشتے تھے، چنانچہ فرشتوں کے حق میں اللہ تعالیٰ کا فرمان ہے:","﴿ بَلْ عِبَادٌ مُكْرَمُونَ ﴾ [الانبیاء: ۲۶]","’’بلکہ وہ سب اس کے باعزت بندے ہیں۔‘‘"],"1112":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ لَا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَنْ ظُلِمَ ﴾ [سورہ نساء: ۱۴۸]","’’برائی کے ساتھ آواز بلند کرنے کو اللہ تعالیٰ پسند نہیں فرماتا مگر مظلوم کو اجازت ہے۔‘‘","امام مجاہد رحمہ اللہ نے کہا: اس آیت کریمہ سے مراد وہ شخص ہے جو کسی کا مہمان ٹھہرا ہو لیکن اس نے ضیافت نہ کی ہو تو مہمان کیلئے جائز ہے کہ وہ اپنے میزبان سے قدرے تند و تیز لہجے میں استفسار کرے تو نے میری ضیافت کیوں نہیں کی۔"],"1113":["رسول اکرم صلی اللہ علیہ وسلم نے سیدنا سعد بن عبادہ رضی اللہ عنہ کے ہاں کشمش کھائی اور فراغت کے بعد یہ دعا دی، (أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ) ...... ’’نیک صالح لوگ تمھارا کھانا کھایا کریں، فرشتے تمھیں دعائیں دیا کریں، اور روزے دار تمھارے ہاں افطار کیا کریں۔‘‘","(صحیح، ابوداود: ۳۸۵۴)"],"1114":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ ﴾ [النحل: ۱۱۵]","’’پھر اگر کوئی شخص بے بس کر دیا جائے نہ وہ خواہشمند ہو اور نہ حد سے گزرنے والا ہو تو یقیناً اللہ بخشنے والا رحم کرنے والا ہے۔‘‘","(غَيْرَ بَاغٍ) کا ایک معنی ہے، وہ بغاوت کرنے والا نہ ہو کہ مضطر نہ ہونے کی صورت میں بھی مردار کھا لے اور (وَلَا عَادٍ) کا معنی ہے گزارہ ہو جانے کے بعد پیٹ بھرنا نہ شروع کر دے۔ دوسرا معنی ہے کہ جتنی مقدار اس کے لیے شریعت نے جائز قرار دی ہے اس سے تجاوز نہ کرے اور (وَلَا عَادٍ) کا معنی ہے کہ سخت مجبور ہو جانے کی صورت میں بھی نہ کھائے اور کوتاہی کر لے۔","(غَيْرَ بَاغٍ) کا تیسرا معنی ہے اسے کھانے کی کوئی چیز دستیاب ہو سکتی ہو مگر وہ اس کی تلاش بھی نہ کرے اور حرام کھانے کے درپے ہو جائے اور (وَلَا عَادٍ) کا معنی ہے شریعت کی مقرر کردہ حد سے آگے نہ بڑھے۔","(غَيْرَ بَاغٍ) کا ایک چوتھا معنی ہے کہ وہ اللہ تعالیٰ کی حرام کردہ اشیاء کو حلال جاننے کا مرتکب نہ ہو اور (وَلَا عَادٍ) کا معنی ہے حد اعتدال سے آگے نہ بڑھے۔ بعض کے نزدیک (غَيْرَ بَاغٍ) کا معنی ہے کہ وہ شخص حکومت اسلامیہ کے خلاف بغاوت کرنے والا نہ ہو، ڈاکو نہ ہو، اگر کوئی شخص زمین میں فساد برپا کرنے اور معصیت کی غرض سے نکلا ہو یا ڈاکہ ڈالنے کیلئے نکلا ہو اور مردار کھانے کیلئے مجبور ہو گیا تو ایسے افراد کے حق میں مردار کھانا حلال نہ ہوگا۔ یہ قول امام مجاہد اور سعید بن جبیر رحمہما اللہ کا ہے۔ امام شافعی رحمہ اللہ کا بھی یہی موقف ہے، ان بزرگوں نے معصیت کا سفر کرنے والے کو مردار خوری کی رخصت نہیں دی۔ اہل رائے نے اہل معاصی کیلئے حالت اضطرار میں مردار خوری کی اجازت دی ہے اور ان کا کہنا ہے کہ بغاوت اور عدوان کا تعلق کھانے سے ہے سفر سے نہیں۔","اور اللہ تعالیٰ کا فرمان ہے:","﴿ فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ ﴾ [سورہ مائدہ: ۳]","’’پس جو شخص شدت کی بھوک میں بے قرار ہو جائے بشرطیکہ کسی گناہ کی طرف اس کا میلان نہ ہو تو یقیناً اللہ معاف کرنے والا اور بہت بڑا مہربان ہے۔‘‘","یہاں مَخْمَصَة کا معنی المجاعة ’’بھوک‘‘ ہے کیونکہ بھوک سے انسان کا پیٹ ساتھ لگ جاتا ہے اور اللہ تعالیٰ کا فرمان ﴿غَيْرَ مُتَجَانِفٍ لِإِثْمٍ﴾ .... کا معنی ہے وہ کسی گناہ کی طرف میلان نہ رکھتا ہو، کسی چیز کی طرف مائل ہو جانے والے کو بزبان عربی (أَجْنَفَ) کہا جاتا ہے۔ اللہ تعالیٰ کا فرمان ہے:","﴿ فَمَنْ خَافَ مِنْ مُوصٍ جَنَفًا ﴾ [سورہ بقرہ: ۱۸۲]","’’جو شخص وصیت کرنے والے کی جانب داری یا گناہ کی وصیت کر دینے سے ڈرے۔‘‘","جناب مسروق رحمہ اللہ نے کہا: جو شخص حرام چیز (مردار) دم مسفوح اور خنزیر کا گوشت کھانے کے لیے مجبور ہو جائے اور نہ کھائے پیے حتیٰ کہ یونہی فوت ہو جائے وہ آگ میں داخل ہوگا اور جناب معمر رحمہ اللہ نے کہا: میں نے اضطراری حالت میں شراب پی لینے کی بات کسی سے نہیں سنی۔","امام زہری رحمہ اللہ نے کہا: اضطراری حالت میں انسانی پیشاب پینا حلال نہ ہوگا خواہ مشکل کتنی بھی شدید کیوں نہ ہو کیونکہ وہ رجس (پلید) ہے اور اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ أُحِلَّ لَكُمُ الطَّيِّبَاتُ ﴾","’’اور تمھارے لیے پاکیزہ چیزیں حلال کی گئی ہیں۔‘‘"],"1115":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ ﴾ [سورہ مائدہ: ۹۰]","’’بات یہی ہے کہ شراب اور جوا اور تھان اور فال نکالنے کے پانسے یہ تیر یہ سب گندی باتیں، شیطانی کام ہیں ان سے بالکل الگ رہو۔‘‘","اللہ عزوجل کا فرمان ہے:","﴿ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا ﴾ [النحل: ۶۷]","’’تم شراب بنا لیتے ہو اور عمدہ روزی بھی۔‘‘","بعض کے نزدیک یہ آیت اس وقت اتری جب شراب حرام نہیں تھی، سیدنا ابن عباس رضی اللہ عنہ نے کہا: سکر سے مراد وہ چیز ہے جو حرام ہے یعنی شراب اور رزق حسن سے مراد حلال چیزیں ہیں یعنی انگور اور کھجوریں وغیرہ۔ اور لفظ السکر ہر اس چیز پر بولا جاتا ہے جو نشہ آور ہو۔"],"1129":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ مِنْ بَيْنِ فَرْثٍ وَدَمٍ لَبَنًا خَالِصًا سَائِغًا لِلشَّارِبِينَ ﴾ [النحل: ۶۶]","’’گوبر اور لہو کے درمیان سے خالص دودھ پلاتے ہیں جو پینے والوں کے لیے سہتا پہنچتا ہے۔‘‘"],"1131":["ارشاد باری تعالیٰ ہے:","﴿ يَا بَنِي آدَمَ قَدْ أَنْزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَارِي سَوْءَاتِكُمْ وَرِيشًا ﴾ [سورہ اعراف: ۲۶]","’’اے آدم کی اولاد! بے شک ہم نے تم پر لباس اتارا ہے جو تمہاری شرمگاہوں کو چھپاتا ہے۔‘‘","’’رِيشًا‘‘ کو ’’رِيَاشًا‘‘ بھی پڑھا گیا ہے، قتیبی نے کہا: ’’الرِّيشُ وَالرِّيَاشُ‘‘ سے مراد ظاہری لباس ہے۔ ایک قول کے مطابق ’’رِيشًا‘‘ کے معنی خوشحالی اور روزی کے ہیں۔ مجاہد نے کہا: ’’رِيشًا‘‘ کے معنی مال اور ہر چیز کے ہیں جو انسان کو ڈھانپ لے، اسی سے پرندے کے پروں کو ’’رِيش‘‘ کہتے ہیں۔ جب بندہ مال والا ہو جائے اور اس کے حالات اچھے ہو جائیں تو کہتے ہیں: ’’تَرَيَّشَ الرَّجُلُ‘‘."],"1136":["’’اشْتِمَالُ الصَّمَّاءِ‘‘ (گونگی بکل) سے کیا مراد ہے؟ حافظ ابن حجر نے کہا: اہل لغت کہتے ہیں: کسی شخص کا ایک کپڑے کو اپنے جسم پر اس طرح لپیٹنا کہ نہ تو وہ اس سے کسی جانب کو بلند کرتا ہو اور نہ اتنی جگہ باقی ہو کہ اس کا ہاتھ نکل سکے۔ ابن قتیبہ نے کہا: ’’صَمَّاء‘‘ کی وجہ تسمیہ یہ ہے کہ اس کی صورت تمام سوراخوں کو بند کر دیتی ہے، اس طرح وہ سخت چٹان کی طرح ہو جاتی ہے، جس میں کوئی سوراخ نہیں ہوتا۔ جبکہ فقہا نے کہا: آدمی اپنے جسم پر کپڑا لپیٹے اور پھر اس کا ایک کنارہ اٹھا کر کندھے پر رکھ دے اور اس طرح اس کی شرمگاہ ننگی ہونے لگے۔ (فتح الباری: ۱/۶۲۹) سنن ابی داود (۴۰۸۰) کی روایت سے اس معنی کی تائید ہوتی ہے، اس میں ہے: رسول اللہ صلی اللہ علیہ وسلم نے لباس کی دو قسموں سے منع کیا ہے: آدمی کا اس طرح گوٹھ مارنا کہ اوپر سے اس کی شرمگاہ ننگی ہو رہی ہو اور اس طرح کپڑا پہننا کہ ایک جانب ننگی رہ جائے اور کپڑا کندھے پر ڈال دے۔ اگرچہ اس حدیث کے ایک راوی سیدنا ابوسعید خدری رضی اللہ عنہ کی تعریف، فقہا کی تعریف سے ملتی جلتی ہے، لیکن علامہ عظیم آبادی کہتے ہیں: لفظ ’’صَمَّاء‘‘ کو سامنے رکھا جائے تو اس معنی کی گنجائش نہیں ملتی، اصمعی کا بیان کردہ معنی اس لفظ کے زیادہ قریب ہے، وہ کہتے ہیں: آدمی کا ایک کپڑے سے اپنا سارا جسم اس طرح ڈھانپ لینا کہ ہاتھ نکالنے کے لیے بھی کوئی سوراخ نہ بچے اور اس طرح وہ اپنے ہاتھوں سے موذی چیزوں سے دفاع نہ کر سکے۔ (عون المعبود: ۱/ ۱۱۲۲) (م،م)"],"1137":["سیدنا ابوذر رضی اللہ عنہ کہتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا، جبکہ آپ سوئے ہوئے تھے اور آپ پر سفید کپڑا تھا۔ (صحیح بخاری: ۵۸۲۷)"],"1138":["سیدنا جابر رضی اللہ عنہ نے کہا: دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ يَوْمَ الْفَتْحِ وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ. رسول اللہ صلی اللہ علیہ وسلم مکہ مکرمہ میں اس حال میں داخل ہوئے کہ آپ پر سیاہ رنگ کا عمامہ تھا۔ (صحیح مسلم: ۱۳۵۹) سیدنا عمرو بن حریث رضی اللہ عنہ نے کہا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ النَّاسَ، وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ. رسول اللہ صلی اللہ علیہ وسلم نے لوگوں سے خطاب کیا، جبکہ آپ صلی اللہ علیہ وسلم نے کالے رنگ کی پگڑی باندھی ہوئی تھی۔ (صحیح مسلم: ۱۳۵۹)"],"1139":["عصفر ایک زرد رنگ کی بوٹی ہے، جس سے رنگائی کا کام کیا جاتا ہے، جن کپڑوں کو عصفر سے رنگا جاتا ہے، وہ سرخ ہو جاتے ہیں۔ (ع،س) عجیب سا لگتا ہے، مردوں کی مردانگی کے خلاف ہے، باوقار نہیں، اس لیے آپ صلی اللہ علیہ وسلم نے اس سے منع فرما دیا ہے۔"],"1140":["سیدنا مغیرہ رضی اللہ عنہ نے کہا: میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ سفر میں تھا، آپ صلی اللہ علیہ وسلم نے اون کا جبہ زیب تن کیا ہوا تھا۔ (صحیح بخاری: ۵۷۹۹)"],"1141":["دیباج: ریشمی قیمتی کپڑا، جس کا تانا بانا ریشم کا ہو۔"],"1145":["سیدہ عائشہ رضی اللہ عنہا سے مروی ہے، وہ کہتی ہیں: کسی نے سیدنا ابو بکر رضی اللہ عنہ سے کہا: یہ رسول اللہ صلی اللہ علیہ وسلم کپڑا اوڑھ کر تشریف لا رہے ہیں۔ (صحیح بخاری: ۳۹۰۵)"],"1157":["سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُ النِّعَالَ السِّبْتِيَّةَ الَّتِي لَيْسَ فِيهَا شَعْرٌ، وَيَتَوَضَّأُ فِيهَا","میں نے نبی کریم صلی اللہ علیہ وسلم کو سبتی جوتے پہنے ہوئے دیکھا، جس میں بال نہیں تھے اور آپ اس کو پہنے ہوئے وضو کرتے تھے۔ (صحیح بخاری: ۵۸۵۱، صحیح مسلم: ۱۱۸۷)"],"1170":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَإِذِ ابْتَلَى إِبْرَاهِيمَ رَبُّهُ بِكَلِمَاتٍ فَأَتَمَّهُنَّ ﴾ [سورۃ بقرہ: ۱۲۴]","’’جب ابراہیم علیہ السلام کو ان کے رب نے کئی باتوں سے آزمایا اور انہوں نے سب کو پورا کر دیا۔‘‘","سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ کلمات سے مراد پانچ امور سر میں ہیں اور پانچ امور باقی جسم میں اور وہ یہ ہیں۔ (۱) کلی کرنا۔ (۲) ناک میں پانی ڈالنا۔ (۳) مسواک کرنا۔ (۴) مونچھیں کاٹنا۔ (۵) مانگ نکالنا۔ (۶) زیر بغل بال اکھیڑنا۔ (۷) زیر ناف بال مونڈنا۔ (۸) ناخنوں کا کاٹنا۔ (۹) استنجاء کرنا۔ (۱۰) ختنہ کرنا۔"],"1181":["سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے کہا: شفا دو چیزوں میں ہے، شہد میں اور قرآن میں۔ قرآن سینے کی بیماریوں کے لیے شفا ہے اور شہد لوگوں کے لیے باعث شفا ہے۔ (صحیح، ابن ماجہ: ۳۴۵۲)"],"1184":["رسول اللہ صلی اللہ علیہ وسلم نے اپنی مرض وفات میں فرمایا: «هَرِيقُوا عَلَيَّ مِنْ سَبْعِ قِرَبٍ لَمْ تُحْلَلْ أَوْكِيَتُهُنَّ» ’’مجھ پر سات مشکیزے پانی کے بہاؤ جن کے بند نہ کھولے گئے ہوں۔‘‘ (صحیح بخاری: ۱۹۸، ۵۷۱۴)"],"1190":["اللہ تعالیٰ کا فرمان ہے: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ﴾ ’’کیا آپ نے انھیں نہیں دیکھا جنھیں کتاب کا کچھ حصہ ملا؟ جو بت اور باطل معبود کا خیال رکھتے تھے۔‘‘ (سورہ نساء: ۵۱) سیدنا عمر رضی اللہ عنہ نے کہا: ﴿الْجِبْت﴾ سے مراد جادو ہے اور ﴿الطَّاغُوت﴾ سے مراد شیطان ہے۔ سیدنا جابر رضی اللہ عنہ نے کہا: ﴿الطَّوَاغِيت﴾.... سے مراد وہ کاہن اور غیب کی خبریں بتانے کا دعویٰ کرنے والے وہ افراد ہیں جن کے شیاطین کے ساتھ گہرے مراسم ہوتے تھے اور ہر قبیلہ میں ایک شخص ایسا ضرور ہوتا تھا۔ جناب عکرمہ نے کہا: (الجبت) سے مراد حبشی کی زبان میں شیطان ہے اور (الطاغوت) سے مراد کاہن ہے۔ ایک قول کے مطابق ﴿الْجِبْت﴾ سے مراد وہ ہر چیز یا شخص ہے جس کی اللہ عزوجل کے علاوہ عبادت کی جائے۔ (اور وہ اپنی عبادت پر راضی ہو) بہرحال ان الفاظ کے یہ سارے معنی بیان کیے گئے ہیں۔"],"1191":["اللہ سبحانہ و تعالیٰ کا فرمان ہے: ﴿وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا فَيُعَلِّمُونَ النَّاسَ السِّحْرَ....﴾ ’’بلکہ یہ کفر شیطانوں کا تھا، وہ لوگوں کو جادو سکھایا کرتے تھے۔‘‘ (سورہ بقرہ: ۱۰۲) اللہ تعالیٰ کا فرمان مقدس ہے: ﴿وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى....﴾ ’’اور جادو گر کہیں سے بھی آئے، کامیاب نہیں ہوتا۔‘‘ (سورہ طہ: ۶۹) اللہ تعالیٰ کا ارشاد گرامی ہے: ﴿وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ....﴾ ’’اور گرہ لگا کر ان میں پھونکنے والیوں کے شر سے (میں اللہ کی پناہ میں آتا ہوں)۔‘‘ (سورہ فلق: ۴) ﴿النَّفَّاثَات﴾.... یہ مؤنث کا صیغہ ہے جو کہ (النفوس) محذوف موصوف کی صفت ہے۔ یعنی گرہوں میں پھونکنے والے نفسوں کی برائی سے پناہ۔ (نفث) بغیر تھوک کے پھونکنے کو کہتے ہیں۔ اللہ سبحانہ و تعالیٰ کا فرمان ہے: ﴿يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى....﴾ ’’اب تو موسیٰ علیہ السلام کو یہ خیال گزرنے لگا کہ ان کی رسیاں اور لکڑیاں ان کے جادو کے زور سے دوڑ بھاگ رہی ہیں۔‘‘ (سورہ طہ: ۶۶) تخیل میں کوئی چیز حقیقت نہیں ہوتی۔ قرآن کے الفاظ سے معلوم ہوتا ہے کہ رسیاں اور لاٹھیاں حقیقت سانپ نہیں تھیں۔"],"1196":["سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: «خَمْسٌ لَا جُنَاحَ عَلَى مَنْ قَتَلَهُنَّ فِي الْحَرَمِ وَالْإِحْرَامِ: الْفَأْرَةُ، وَالْغُرَابُ، وَالْحِدَأَةُ، وَالْعَقْرَبُ، وَالْكَلْبُ الْعَقُورُ»...... ’’پانچ جانور ایسے ہیں جنھیں حرم میں اور حالت احرام میں بھی مار ڈالنے میں کوئی گناہ نہیں۔ چوہا، کوا، چیل، بچھو اور کاٹ لینے والا کتا۔‘‘ (صحیح بخاری: ۱۸۲۶، صحیح مسلم: ۱۱۹۹)"],"1197":["اللہ سبحانہ و تعالیٰ سیدنا ابراہیم علیہ السلام کی بابت خبر دیتے ہوئے ارشاد فرماتے ہیں: ﴿إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ فَانْظُرْ مَاذَا تَرَى قَالَ يَا أَبَتِ افْعَلْ مَا تُؤْمَرُ....﴾ ’’میں خواب میں اپنے آپ کو تجھے ذبح کرتے ہوئے دیکھ رہا ہوں۔ اب تو بتا کہ تیری کیا رائے ہے۔‘‘ (سورہ صافات: ۱۰۲)","معلوم ہوا کہ خواب اپنی ایک حقیقت رکھتا ہے۔ یہ کوئی بے بنیاد چیز نہیں کہ صرف واہمہ کہہ کر اس کی حیثیت ختم کر دی جائے، نیز پیغمبر کا خواب وحی اور حکم الہی ہوتا ہے۔ (ع،س)"],"1202":["اللہ سبحانہ وتعالیٰ نے سیدنا یوسف علیہ السلام کے متعلق فرمایا ہے:","﴿ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ﴾ [سورہ یوسف: ۴]","’’میں نے گیارہ ستاروں کو اور سورج چاند کو دیکھا کہ وہ سب مجھے سجدہ کر رہے ہیں۔‘‘","نیز اللہ تعالیٰ کا فرمان ذی شان ہے:","﴿ وَرَفَعَ أَبَوَيْهِ عَلَى الْعَرْشِ وَخَرُّوا لَهُ سُجَّدًا وَقَالَ يَا أَبَتِ هَذَا تَأْوِيلُ رُؤْيَايَ مِنْ قَبْلُ ﴾ [سورہ یوسف: ۱۰۰]","’’اور اپنے تخت پر اپنے ماں باپ کو اونچا بٹھایا اور سب اس کے سامنے سجدے میں گر گئے۔ تب کہا کہ ابا جی! یہ میرے پہلے کے خواب کی تعبیر ہے۔‘‘"],"1209":["اللہ سبحانہ وتعالی کا فرمان ہے:","﴿ وَقَالَ الْمَلِكُ إِنِّي أَرَى سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ ﴾ [سورہ یوسف: ۴۳]","’’بادشاہ نے کہا: میں نے خواب میں دیکھا ہے کہ سات موٹی تازی فربہ گائیں ہیں جن کو سات لاغر ودبلی پتلی گائیں کھا رہی ہیں۔‘‘"],"1219":["اللہ سبحانہ وتعالی کا فرمان ہے:","﴿ قَالَتْ يَا أَيُّهَا الْمَلَأُ إِنِّي أُلْقِيَ إِلَيَّ كِتَابٌ كَرِيمٌ ﴾ [سورہ نمل: ۲۹]","’’وہ کہنے لگی: اے سردارو! میری طرف ایک باوقعت خط ڈالا گیا ہے۔‘‘","یعنی ایسا مکتوب جو سر بمہر ہے یا یہ کہ جس کا مضمون اور اس کے مندرجات با مقصد اور شاندار ہیں یا خط لکھنے والا معزز اور صاحب جلال ہے یا یہ کہ اس کے آغاز میں «بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ» مرقوم ہے اس لیے وہ باوقعت ہے۔"],"1220":["اللہ سبحانہ وتعالی کا فرمان ہے:","﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّى تَسْتَأْنِسُوا وَتُسَلِّمُوا عَلَى أَهْلِهَا ﴾ [سورہ نور: ۲۷]","’’اے ایمان والو! اپنے گھروں کے سوا اور گھروں میں نہ جاؤ جب تک کہ اجازت نہ لے لو اور وہاں کے رہنے والوں کو سلام نہ کرلو۔‘‘","سیدنا ابن عباس رضی اللہ عنہ نے: ﴿تَسْتَأْنِسُوا﴾ کی بجائے ﴿حَتَّى تَسْتَأْذِنُوا﴾ پڑھا ہے۔"],"1227":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ فَافْسَحُوا ﴾ [سورہ مجادلہ: ۱۱]","’’مجلسوں میں ذرا کشادگی پیدا کرو۔‘‘"],"1235":["فائدہ: (تَشْمِيت) کے معنی ہیں: خیر و برکت کی دعا کرنا۔ بعض کے نزدیک معنی ہیں: اللہ تعالیٰ تجھے ایسی چیزوں سے دور رکھے جن سے تیرے دشمن خوش ہوں۔ مندرجہ بالا عنوان اور اس کی ذیل میں آنے والی احادیث مبارکہ سے معلوم ہوا کہ دعائے خیر کا مستحق وہی ہے جو سنت کے مطابق چھینک آنے پر الحمد للہ کہے ورنہ جواب دینے کی ضرورت نہیں، اگر اسے مسئلے کا علم نہیں تو اسے سمجھا دینا چاہیے۔ (ع، ہس)"],"1238":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَاقْصِدْ فِي مَشْيِكَ ﴾ [سورہ لقمان: ۱۹]","’’اپنی رفتار میں میانہ روی اختیار کرو۔‘‘","اللہ عزوجل کا مزید ارشاد ہے:","﴿ وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا ﴾ [سورہ لقمان: ۱۸]","’’اور زمین پر اترا کر نہ چل۔‘‘","جناب یزید بن ابی حبیب نے اللہ کے فرمان:","﴿ وَاقْصِدْ فِي مَشْيِكَ ﴾ [سورہ لقمان: ۱۹]","’’اپنی رفتار میں میانہ روی اختیار کرو۔‘‘","کے بارے میں کہا کہ اس سے مراد تیز چال ہے جو شرف و وقار کے خلاف ہو۔"],"1239":["سیدنا جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو دیکھا کہ آپ تکیہ پر بائیں ہاتھ کی ٹیک لگائے ہوئے تھے۔ (صحیح، ابوداود: ۴۱۴۳، ترمذی: ۲۷۷۰)"],"1240":["سیدنا براء رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم رات کو اپنی خواب گاہ میں قرار پکڑتے تو اپنا دایاں ہاتھ اپنے دائیں رخسار کے نیچے رکھتے۔ (شمائل ترمذی: ۲/۷۳، ورواہ البخاری عن حذیفہ: ۶۳۱۴) جناب عباد بن تمیم اپنے چچا سے بیان کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو مسجد میں چت لیٹے ہوا دیکھا۔ آپ نے اپنی ایک ٹانگ دوسری ٹانگ پر رکھی ہوئی تھی۔ (صحیح بخاری: ۶۲۸۷، صحیح مسلم: ۲۱۰۰)"],"1242":["سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آج رات میرے ہاں بیٹے کی پیدائش ہوئی تو میں نے اس کا نام اپنے باپ ابراہیم علیہ السلام کے نام پر رکھ دیا ہے۔‘‘ (صحیح، ابوداود: ۳۱۲۶)"],"1252":["رجز ان جملوں یا اشعار کو کہتے ہیں جو جنگ میں مخالف کا سامنا ہوتے وقت اپنی برتری کے اظہار کے لیے پڑھے جاتے ہیں۔ (ع، س)"],"1253":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ. أَلَمْ تَرَ أَنَّهُمْ فِي كُلِّ وَادٍ يَهِيمُونَ ﴾ [سورہ بقرہ: ۲۲۴، ۲۲۵]","’’شاعروں کی پیروی وہ کرتے ہیں جو بہکے ہوئے ہوں، کیا آپ نے نہیں دیکھا کہ شاعر ایک ایک بیابان میں سرگشتہ پھرتے ہیں۔‘‘","امام زہری رحمہ اللہ نے کہا: آیت کریمہ میں اختیار کردہ پیرایہ کلام ایسے ہی ہے جیسے تو کہے: (أَنَا لَكَ فِي وَادٍ وَأَنْتَ لِي فِي وَادٍ) ’’میں تیرے لیے کچھ سوچتا ہوں تو میرے لیے کچھ اور سوچتا ہے۔ میں تیرا بھلا سوچتا ہوں تو میرا نقصان۔‘‘ مطلب یہ ہے کہ شاعروں کی اکثریت چونکہ ایسی ہوتی ہے کہ وہ مدح و ذم میں، اصول و ضابطے کے بجائے ذاتی پسند و ناپسند کے مطابق اظہار رائے کرتی ہے۔ علاوہ ازیں اس میں مبالغہ آرائی سے کام لیتے ہیں۔ شاعرانہ تخیلات میں کبھی ادھر اور کبھی ادھر بھٹکتے ہیں۔ مدح میں جھوٹ بولتے ہیں اور مذمت میں حد سے گزر جاتے ہیں۔"],"1254":["اللہ تعالیٰ کا فرمان ہے:","﴿ إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ ﴾ [سورہ مائدہ: ۹۰]","’’اے ایمان والو! بات یہی ہے کہ شراب اور جوا اور تھان اور فال نکالنے کے پانسے تیر یہ سب گندی باتیں ہیں۔‘‘","اس سے مراد وہ اونٹ ہیں جن پر اہل عرب جوا لگایا کرتے تھے۔ اسے میسر کہا جاتا ہے کیونکہ اسے کئی حصوں میں بانٹا جاتا تھا اور جس چیز کے مختلف حصے کر دیے جائیں اسے اسی لفظ سے تعبیر کیا جاتا ہے یعنی يَسَرْتَهُ کا معنی ہے: ’’تو نے حصے لگا دیے۔‘‘ (الیاسر) ’’وہ شخص جو اونٹ کا گوشت تقسیم کرتا ہے۔‘‘ اہل عرب کے مقامات (جوے والے) طریقے۔ (يَسَرَ الْقَوْمَ) کا معنی ہے: ’’لوگوں نے جوا کھیلا۔‘‘ جوے باز کو عربی میں ’’رَجُلٌ يَسَرٌ‘‘ یا ’’رَجُلٌ يَاسِرٌ‘‘ کہا جاتا ہے۔"],"1255":["اللہ سبحانہ وتعالیٰ کا فرمان ہے: ﴿وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حُسْنًا﴾ ’’ہم نے انسان کو اپنے والدین کے ساتھ احسان کرنے کی تاکید کی ہے۔‘‘ (سورہ عنکبوت: ۸) اور اللہ تعالیٰ نے سیدنا یحییٰ علیہ السلام کی تعریف کرتے ہوئے فرمایا: ﴿وَبَرًّا بِوَالِدَيْهِ﴾ ’’اور وہ اپنے ماں باپ کے ساتھ حسن سلوک کرنے والے تھے۔‘‘ (سورہ مریم: ۱۴) اور سیدنا عیسیٰ علیہ السلام کی تعریف کرتے ہوئے فرمایا:","﴿ وَبَرًّا بِوَالِدَتِي ﴾ [سورہ مریم: ۳۲]","’’اور اس نے مجھے اپنی والدہ کا خدمت گزار بنایا ہے۔‘‘","﴿البر﴾ کا ترجمہ ہے: ’’حسن سلوک کرنا، پورا کرنا اور ملانا۔‘‘ (بَرَرْتُ وَالِدِي) کا معنی ہے میں نے اپنے والد سے اچھا سلوک کیا۔ اور (بَرَرْتُ فِي يَمِينِي) کا معنی ہے: میں نے اپنی قسم پوری کی۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ ﴾","’’اور تیرے رب نے فیصلہ کر دیا ہے کہ عبادت صرف ایک رب کی کرو۔‘‘","جناب مجاہد نے کہا: یعنی تیرے رب نے اس بات کا حکم فرمایا ہے۔","﴿ وَبِالْوَالِدَيْنِ إِحْسَانًا ﴾ [سورہ اسراء: ۲۳]","’’اور ماں باپ کے ساتھ اچھا سلوک کرو۔‘‘"],"1256":["اللہ تعالیٰ کا فرمان ہے:","﴿ وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبُهُمَا فِي الدُّنْيَا مَعْرُوفًا ﴾ [سورہ لقمان: ۱۵]","’’اور اگر وہ دونوں تجھ پر اس بات کا دباؤ ڈالیں کہ تو میرے ساتھ شرک کرے جس کا تجھے علم نہ ہو تو تو ان کا کہنا نہ ماننا، ہاں دنیا میں ان کے ساتھ اچھی طرح بسر کرنا۔‘‘"],"1257":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلَاهُمَا فَلَا تَقُلْ لَهُمَا أُفٍّ ﴾ [سورہ بنی اسرائیل: ۲۳]","’’اگر تیری موجودگی میں ان میں سے ایک یا وہ دونوں بڑھاپے کو پہنچ جائیں تو ان کے آگے اف تک نہ کہنا۔‘‘","اس آیت کریمہ کا مطلب ہے کہ بڑھاپے میں والدین کے ساتھ کوئی ایسا رویہ نہ اپنایا جائے جن میں ان کی ہلکی سی بھی دل آزاری اور دل شکنی کا شائبہ ہو یعنی ان کے سامنے اُف تک کہنے سے باز رہا جائے۔ (اف) اور (تُف) ناخنوں میں پھنسی ہوئی معمولی میل کچیل کو کہتے ہیں۔ عرب محاورہ میں جو چیز ذرا سی طبیعت پر ناگوار گزرے اور ہلکے سے بوجھل پن کا باعث بنے تو اس موقع پر لفظ اُف بول دیا جاتا ہے۔ امام مجاہد رحمہ اللہ نے کہا: تو والدین سے ملول خاطر نہ ہو جس طرح بچپن میں وہ تم سے اکتاتے نہ تھے۔ اللہ عزوجل کا فرمان ہے:","﴿ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ ﴾ [سورہ بنی اسرائیل: ۲۴]","’’اور عاجزی اور محبت کے ساتھ ان کے سامنے تواضع کا بازو پست رکھے رکھنا۔‘‘","امام عطاء رحمہ اللہ نے کہا: والدین کی عظمت اور رفعت شان کا تقاضا ہے کہ ان کے سامنے ہاتھ بالکل نہ اٹھائے جائیں اور نہ ان کے ساتھ دست درازی کی جائے۔ جناب عروہ نے کہا: والدین جس چیز کو پسند کریں انہیں اس سے محروم نہ رکھا جائے۔","پرندہ جب اپنے بچوں کو اپنے سایہ شفقت میں لیتا ہے تو ان کے لیے اپنے بازو پست کر دیتا ہے۔ یعنی تو بھی والدین کے ساتھ اسی طرح اچھا اور پرشفقت معاملہ کرنا اور ان کی اسی طرح کفالت کر جس طرح انہوں نے بچپن میں نرمی کی۔ (ع، س) نبی اکرم صلی اللہ علیہ وسلم کا فرمان ہے: «أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ: الْإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَشَهَادَةُ الزُّورِ»...... ’’کیا میں تمہیں سب سے بڑے گناہوں کی خبر نہ دوں؟ اللہ کا شریک ٹھہرانا، ماں باپ کی نافرمانی کرنا اور جھوٹی گواہی دینا۔‘‘ (صحیح بخاری: ۵۹۷۶، صحیح مسلم: ۸۷)"],"1258":["اللہ تعالیٰ کا فرمان ذی شان ہے:","﴿ وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ ﴾ [سورہ نساء: ۱]","’’اللہ سے ڈرو کہ جس کے نام پر ایک دوسرے سے مانگتے ہو اور رشتے ناطے توڑنے سے بھی بچو۔‘‘","بعض علماء نے (الارحام) کو مکسور پڑھا ہے یعنی تَسَاءَلُونَ بِهِ وَبِالْأَرْحَامِ.... اس صورت میں معنی ہوگا کہ تم ایک دوسرے سے اللہ تعالیٰ کا اور رشتہ داری کا واسطہ دے کر رحم اور ترس کی اپیل کرتے ہو۔ جس طرح اہل عرب کہا کرتے تھے: (نَشَدْتُكَ بِاللَّهِ وَبِالرَّحِمِ) ’’میں تجھے اللہ اور رشتہ داری کا واسطہ دیتا ہوں۔‘‘"],"1264":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَلَا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ ﴾ [سورہ انعام: ۱۵۲]","’’اور یتیم کے مال کے پاس نہ جاؤ مگر ایسے طریقے سے جو کہ مستحسن ہے۔‘‘","اللہ عزوجل کا فرمان ہے:","﴿ وَيَسْأَلُونَكَ عَنِ الْيَتَامَى قُلْ إِصْلَاحٌ لَهُمْ خَيْرٌ ﴾ [سورہ بقرہ: ۲۲۰]","’’اور تجھ سے یتیموں کے بارے میں سوال کرتے ہیں آپ کہہ دیجیے کہ ان کی خیر خواہی بہتر ہے۔‘‘","اللہ عزوجل کا ارشاد ہے:","﴿ فَذَلِكَ الَّذِي يَدُعُّ الْيَتِيمَ ﴾ [سورہ ماعون: ۲]","’’یہی وہ ہے جو یتیم کو دھکے دیتا ہے۔‘‘","یعنی جو یتیم کو پوری شدت اور تکبر کے ساتھ دھکے دیتا ہے۔ اللہ تعالیٰ کا فرمان ذی شان ہے:","﴿ يُدَعُّونَ إِلَى نَارِ جَهَنَّمَ دَعًّا ﴾ [سورہ طور: ۱۳]","’’جس دن وہ دھکے دے دے کر آتش جہنم کی طرف لائے جائیں گے۔‘‘"],"1266":["اللہ سبحانہ و تعالیٰ کا ارشاد ہے:","﴿ وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى ﴾ [سورہ مائدہ: ۲]","’’نیکی اور پرہیزگاری کے کاموں میں ایک دوسرے کا تعاون کرو۔‘‘"],"1267":["نبی اکرم صلی اللہ علیہ وسلم کا فرمان ہے: ’’سات قسم کے آدمی ایسے ہیں کہ اللہ تعالیٰ انھیں اپنے سائے میں جگہ دے گا۔‘‘ اور آپ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ دو آدمی جو ایک دوسرے سے صرف اللہ تعالیٰ کے لیے محبت کرتے ہیں۔‘‘ (صحیح بخاری: ۶۶۰، صحیح مسلم: ۱۰۳۱) سیدنا ابو جحیفہ رضی اللہ عنہ نے کہا: نبی صلی اللہ علیہ وسلم نے سیدنا سلمان فارسی رضی اللہ عنہ اور سیدنا ابو درداء رضی اللہ عنہ کے مابین بھائی چارہ قائم کیا۔ (صحیح بخاری: ۱۹۶۸) سیدنا عبدالرحمن بن عوف رضی اللہ عنہ نے کہا کہ جب ہم مدینہ منورہ آئے تو نبی صلی اللہ علیہ وسلم نے میرے اور سیدنا سعد بن ربیع رضی اللہ عنہ کے درمیان بھائی چارہ قائم کیا۔ (صحیح بخاری: ۳۷۸۰) سیدنا انس رضی اللہ عنہ نے کہا کہ نبی صلی اللہ علیہ وسلم نے سیدنا ابو عبیدہ اور سیدنا ابو طلحہ رضی اللہ عنہما کے درمیان بھائی چارہ قائم کیا۔ (صحیح مسلم: ۲۵۶۶)"],"1268":["اللہ تعالیٰ کا فرمان ہے:","﴿ إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَيَجْعَلُ لَهُمُ الرَّحْمَنُ وُدًّا ﴾ [سورہ مریم: ۹۶]","’’بے شک جو ایمان لائے ہیں اور جنہوں نے شائستہ اعمال کیے ہیں ان کے لیے اللہ رحمٰن محبت پیدا کر دے گا۔‘‘","سیدنا ابن عباس رضی اللہ عنہما کا قول ہے: یعنی دنیا میں نیک اور پارسا لوگوں کے دلوں میں اس کی محبت پیدا کر دی جائے گی۔"],"1276":["سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: «إِنَّ اللَّهَ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ» ’’بے شک اللہ تعالیٰ تمام معاملات میں نرمی کو پسند فرماتا ہے۔‘‘ (صحیح بخاری: ۶۰۲۴، صحیح مسلم: ۲۱۶۵)"],"1277":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَإِنَّكَ لَعَلَى خُلُقٍ عَظِيمٍ ﴾ [سورہ قلم: ۴]","’’اور بے شک آپ بہت بڑے (عمدہ) اخلاق پر ہیں۔‘‘","سیدہ عائشہ رضی اللہ عنہا نے کہا: آپ کا اخلاق قرآن مجید تھا۔","اللہ تبارک وتعالیٰ کا مزید ارشاد پاک ہے:","﴿ خُذِ الْعَفْوَ ﴾ [سورہ اعراف: ۱۹۹]","’’آپ درگزر کو اختیار کیجیے۔‘‘","یعنی لوگ جس قسم کے اخلاق کا آپ سے مظاہرہ کریں برداشت کیجیے اور وہی قبول فرما لیجیے۔","سیدنا عبداللہ بن زبیر رضی اللہ عنہ نے اللہ تعالیٰ کے فرمان: ﴿خُذِ الْعَفْوَ﴾ کے متعلق کہا کہ اس آیت کریمہ میں نبی صلی اللہ علیہ وسلم کو حکم دیا گیا ہے کہ لوگوں کے رویے پر آپ عفو و درگزر سے کام لیں۔ یقیناً آپ کی شان بلند اور مقام رفیع کے حقیقی تقاضوں کو پورا کرنے سے وہ قاصر ہیں۔","سیدنا ابن عباس رضی اللہ عنہ نے اللہ سبحانہ وتعالیٰ کے فرمان:","﴿ ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ ﴾ [سورہ مومنون: ۹۶]","’’برائی کو اس طریقے سے دور کریں جو سراسر بھلائی والا ہو۔‘‘","کے بارے میں فرماتے ہیں: یعنی کسی کے غصے کے مقابلے میں صبر و ضبط سے کام لو اور بداخلاقی کے مقابلے میں معاف کر دینے کی پالیسی پر عمل کرو، جب تم اس قسم کا رویہ اپناؤ گے تو اللہ تعالیٰ تمہیں محفوظ رکھیں گے، تمہارا دشمن سرنگوں ہو جائے گا بلکہ تمہارا گہرا دوست بن جائے گا۔ اللہ تعالیٰ کا فرمان ہے:","﴿ وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ ﴾ [سورہ شوریٰ: ۴۰]","’’اور برائی کا بدلہ اسی جیسی برائی ہے اور جو معاف کر دے اور اصلاح کر لے اس کا اجر اللہ کے ذمے ہے۔‘‘","اللہ تعالیٰ کا فرمان ہے:","﴿ وَأْمُرْ قَوْمَكَ يَأْخُذُوا بِأَحْسَنِهَا ﴾ [سورہ اعراف: ۱۴۵]","’’اور اپنی قوم کو حکم کرو کہ ان کے اچھے اچھے احکام پر عمل کریں۔‘‘","یعنی ظالم سے بدلہ لینا اگرچہ شریعت میں جائز ہے مگر معاف کر دینا زیادہ اچھا ہے۔"],"1279":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ ﴾ [سورہ شعراء: ۲۱۵]","’’اس کے ساتھ فروتنی سے پیش آئیے، جو بھی اہل ایمان میں سے آپ کی تابعداری کرے۔‘‘","یعنی آپ کی طرف سے ان کے لیے نرمی، کشادہ دلی اور نفسی خوشی کا برتاؤ ہونا چاہیے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ ﴾ [سورہ اسراء: ۲۴]","’’اور عاجزی اور محبت کے ساتھ ان کے سامنے تواضع کا بازو پست رکھے رکھنا۔‘‘","اللہ تعالیٰ کا فرمان ہے:","﴿ خُذِ الْعَفْوَ ﴾ [سورہ اعراف: ۱۹۹]","’’آپ درگزر کو اختیار کیجیے۔‘‘","امام مجاہد رحمہ اللہ نے کہا: اس کا مطلب ہے کہ لوگوں کے ظاہری اعمال و کردار کو قبول کرو اور ٹوہ مت لگاؤ۔","اللہ سبحانہ وتعالیٰ نے اہل ایمان کی صفت بیان کرتے ہوئے کہا:","﴿ أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ ﴾ [سورہ مائدہ: ۵۴]","’’وہ نرم دل ہوں گے مسلمانوں پر۔‘‘","یعنی اہل ایمان کے ساتھ ان کا معاملہ نہایت نرم دلی اور درگزر والا ہوگا۔ اس کا مطلب یہ ہرگز نہیں وہ ذلیل اور گئے گزرے لوگ ہوں گے بلکہ ان کا معاملہ اس شعر کی طرح ہوگا۔","ہو حلقہ یاراں تو بریشم کی طرح نرم","رزم حق و باطل ہو تو فولاد ہے مومن","اللہ عزوجل کا فرمان ہے:","﴿ أَعِزَّةٍ عَلَى الْكَافِرِينَ ﴾ [سورہ مائدہ: ۵۴]","’’کفار پر سخت اور تیز ہوں گے۔‘‘","اللہ رب العزت کا فرمان ہے:","﴿ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ ﴾","’’اور اگر آپ بدزبان اور سخت دل ہوتے تو یہ سب آپ کے پاس سے چھٹ جاتے۔‘‘","یعنی آپ سے دور ہو جاتے۔ ’’الفظ‘‘ کا معنی ہے سخت مزاج، تندخو اور بدخلق۔ لفظ ’’فظ‘‘ کا لغوی استعمال کچھ اس طرح ہے کہ جب کہیں پانی بالکل دستیاب نہ ہو اور جان کے لالے پڑ جائیں تو اونٹ کی اوجھڑی کو نچوڑ کر چند گھونٹ پانی حاصل کیا جائے، گویا اوجھڑی سے حاصل شدہ گھونٹوں کو ’’فظ‘‘ کہتے ہیں۔ پھر اس کا استعمال ایسے شخص پر ہونے لگا جس میں خشکی ہی خشکی ہو اور نرمی نام کی کوئی چیز نہ ہو، وہ وسیع المشرب ہونے کی بجائے تنگ نظر اور پیوست کا مارا ہوا ہو۔"],"1281":["اللہ تعالیٰ کا فرمان ذی شان ہے:","﴿ إِذَا تَنَاجَيْتُمْ فَلَا تَتَنَاجَوْا بِالْإِثْمِ وَالْعُدْوَانِ ﴾ [سورہ مجادلہ: ۹]","’’اے ایمان والو! تم جب سرگوشی کرو تو یہ سرگوشیاں گناہ اور ظلم و زیادتی والی نہ ہوں۔‘‘"],"1282":["اللہ سبحانہ وتعالیٰ کا فرمان:","﴿ إِذَا نَصَحُوا لِلَّهِ وَرَسُولِهِ ﴾ [سورہ توبہ: ۹۱]","’’بشرطیکہ وہ اللہ اور اس کے رسول کی خیر خواہی کرتے رہیں۔‘‘","اللہ تعالیٰ نے سیدنا نوح علیہ السلام کے متعلق خبر دیتے ہوئے فرمایا:","﴿ وَأَنْصَحُ لَكُمْ ﴾ [سورہ اعراف: ۶۲]","’’اور میں تمہاری خیر خواہی کرتا ہوں۔‘‘","سیدنا ہود علیہ السلام کی بابت بتایا کہ انہوں نے اپنی قوم سے کہا:","﴿ وَأَنَا لَكُمْ نَاصِحٌ أَمِينٌ ﴾ [سورہ اعراف: ۶۸]","’’اور میں تمہارا امانتدار خیرخواہ ہوں۔‘‘","نیز سیدنا شعیب علیہ السلام اور سیدنا صالح علیہ السلام کی بابت فرمایا:","﴿ وَنَصَحْتُ لَكُمْ ﴾ [سورہ اعراف: ۷۹]","’’اور میں نے تمہاری خیر خواہی کی۔‘‘"],"1289":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا ﴾ [سورہ حجرات: ۱۲]","’’اے ایمان والو! بدگمانیوں سے بچو، یقین مانو کہ بعض بدگمانیاں گناہ ہیں اور بھید نہ ٹٹولا کرو۔‘‘","اللہ سبحانہ وتعالیٰ کا مزید فرمان ہے:","﴿ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴾ [سورہ فلق: ۵]","’’اور حسد کرنے والوں کی برائی سے جب وہ حسد کرتے ہیں۔‘‘","اللہ تعالیٰ کا فرمان ہے:","﴿ أَمْ يَحْسُدُونَ النَّاسَ عَلَى مَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ ﴾ [سورہ نساء: ۵۴]","’’کیا یہ لوگوں سے حسد کرتے ہیں اس پر جو اللہ تعالیٰ نے اپنے فضل سے انہیں دیا ہے۔‘‘","اللہ تعالیٰ کا فرمان ہے:","﴿ فَمَا اخْتَلَفُوا إِلَّا مِنْ بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ ﴾ [سورہ جاثیہ: ۱۷]","’’پھر انہوں نے اپنے پاس علم کے پہنچ جانے کے بعد آپس کی ضد اور بحث سے ہی اختلاف برپا کر ڈالا ہے۔‘‘","’’بغی‘‘ سے مراد حسد ہے اور ظلم کو بھی ’’بغی‘‘ کہتے ہیں کیونکہ حاسد درحقیقت ظالم ہوتا ہے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ إِنَّمَا بَغْيُكُمْ عَلَى أَنْفُسِكُمْ ﴾ [سورہ یونس: ۲۳]","’’تمہاری سرکشی تمہارے لیے وبال ہونے والی ہے۔‘‘"],"1295":["اللہ سبحانہ وتعالیٰ ہے:","﴿ وَلَا تَنَابَزُوا بِالْأَلْقَابِ ﴾ [سورہ حجرات: ۱۱]","’’اور نہ کسی کو برے لقب دو۔‘‘","’’نبز‘‘ سے مراد کسی کا نام ٹکنا ہے۔ یعنی بطور استہزا اور تحقیر لوگوں کو برے ناموں سے نہ بلاؤ۔"],"1296":["نبی صلی اللہ علیہ وسلم نے فرمایا: ’’مومن کو گالی دینا اس کو قتل کر دینے کے مترادف ہے۔‘‘ (صحیح بخاری: ۶۰۴۷)"],"1297":["اللہ تعالیٰ کا فرمان ہے:","﴿ وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا ﴾ [سورہ حجرات: ۱۲]","’’اور نہ تم میں سے کوئی کسی کی غیبت کرے۔‘‘","اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ ﴾ [سورہ ہمزہ: ۱]","’’بڑی خرابی ہے ہر ایسے شخص کی جو عیب ٹٹولنے والا غیبت کرنے والا ہو۔‘‘","بعض کے نزدیک ﴿لُمَزَةٍ﴾ وہ شخص ہے جو رو در رو برائی کرے اور ﴿هُمَزَةٍ﴾ وہ شخص جو پیچھے پیچھے غیبت کرے۔ بعض دونوں کو ہم معنی سمجھتے ہیں۔"],"1301":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ ﴾ [سورہ قلم: ۱۱]","’’بے وقار، کمینہ، عیب گو، چغل خور۔‘‘","اللہ تعالیٰ کا فرمان ہے:","﴿ وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ ﴾ [سورہ تبت: ۴]","’’اور اس کی بیوی بھی (جنہی ہے) جو لکڑیاں ڈھونے والی ہے۔‘‘","مراد کہ چغل خوری کرتی تھی۔ مزید فرمایا:","﴿ فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ ﴾ [ایضا: ۵]","’’اس کی گردن میں مضبوط بٹی ہوئی رسی ہوگی۔‘‘","مونج کی بٹی ہوئی مضبوط رسی، اس سے مراد آگ کی زنجیر ہے۔"],"1303":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ ﴾ [سورہ توبہ: ۱۱۹]","’’اے ایمان والو! اللہ سے ڈرو اور سچوں کے ساتھ رہو۔‘‘","اللہ تعالیٰ کا مزید فرمان ہے:","﴿ قُتِلَ الْخَرَّاصُونَ ﴾ [سورہ ذاریات: ۱۰]","’’بے سند باتیں کرتے والے غارت کر دیے گئے۔‘‘","’’جھوٹے لوگ‘‘ مراد ہیں جو اللہ تعالیٰ کے متعلق اندازے اور اٹکل سے بغیر یقین و علم کے باتیں کرتے ہیں۔ کھجور کے درختوں کے اوپر موجود پھل کے اندازے کو ’’خرص النخیل‘‘ کہتے ہیں۔ اس لیے کہ وہاں بھی محض تخمینہ ہوتا ہے اور یقینی بات نہیں ہوتی۔"],"1304":["مندرجہ بالا جملہ کے قائل سیدنا عمران بن حصین رضی اللہ عنہ ہیں۔ سیدنا عمر رضی اللہ عنہ نے کہا: ’’مَعَارِيض‘‘ سے مراد ایسی ذو معنی بات ہے جس سے آدمی صریح جھوٹ بولنے سے بچ جائے۔ ایسی بات کے دو پہلو ہوتے ہیں، سچ اور جھوٹ یا ظاہر اور باطن۔ جہاں شرعی مصلحت درپیش ہو وہاں ایسا انداز اختیار کرنا جائز ہے اور اسے ’’توریہ‘‘ کہتے ہیں۔ (مَنْدُوحَة) ایسا بیجا یا کلام اختیار کرنے میں وسعت اور گنجائش ہے یعنی جس سے جھوٹ بولنے سے جان چھوٹ جائے اور فساد بھی برپا نہ ہو۔ (نَدَحْتُ الشَّيْءَ نَدْحًا) کا معنی ہے: ’’میں نے فلاں چیز کو کشادہ اور فراخ کر دیا ہے۔‘‘ لیکن اپنے مسلمان بھائی کے ساتھ بغیر شرعی ضرورت کے ایسا انداز اختیار کرنا کہ اس کے ذریعے سے کسی حق کا انکار ہو یا کوئی حق مارے، تو یہ جھوٹ اور دھوکا دہی ہے اور ناجائز ہے۔ (ع، بس)"],"1305":["اللہ سبحانہ وتعالیٰ کا فرمان ہے:","﴿ وَإِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَ ﴾ [سورہ شوریٰ: ۳۷]","’’اور غصے کے وقت (بھی) معاف کر دیتے ہیں۔‘‘","اللہ عزوجل کا فرمان ہے:","﴿ وَالْكَاظِمِينَ الْغَيْظَ ﴾ [سورہ آل عمران: ۱۳۴]","’’اور غصہ پینے والے۔‘‘","اللہ تعالیٰ کا فرمان اقدس ہے:","﴿ يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ ﴾ [سورہ توبہ: ۷۳]","’’اے نبی! کافروں اور منافقوں سے جہاد جاری رکھو اور ان پر سخت ہو جاؤ۔‘‘"]})